1	// Fringe Planner — page logic.
2	//
3	// Self-contained ES module: no globals shared with the home site's js/app.js.
4	// Wires the real computation engine (./lib/engine.js, ./lib/favourites.js —
5	// pure, untouched here) to the two-screen UI described in
6	// plan/design/mock.html + plan/design/DESIGN_NOTES.md.
7	//
8	// Screen 1 (input): drag/drop or pick a favourites CSV, or load the bundled
9	//   sample. Screen 2 (calendar): one lane per matched favourite across
10	//   August 2026, with a draggable date window and a start-time range slider
11	//   that filter live via engine.summarize().
12	
13	import { parseFavourites, urlFromSlug } from "./lib/favourites.js";
14	import { buildIndex, matchFavourites, summarize } from "./lib/engine.js";
15	
16	// ES modules are always strict mode, so no "use strict" directive is needed.
17	
18	// --- Constants --------------------------------------------------------
19	
20	const DATA_URL = "../data/normalized/shows.json";
21	const SAMPLE_URL = "./sample-favourites.csv";
22	
23	const YEAR = 2026;
24	const MONTH = "08"; // August, 2-digit
25	const DAYS_IN_MONTH = 31; // Aug 1–31 is the axis this calendar draws.
26	// TODO: the underlying data actually spans 2026-07-24 through 2026-08-31
27	// (previews before Aug 1, and a handful of performances after Aug 31 do not
28	// occur — the latest date in the dataset is Aug 31 itself). Performances
29	// outside the Aug 1–31 axis simply fall off the calendar; this is expected
30	// per the spec and rare in practice (previews are the main case).
31	const FEST_END_DAY = 25; // Core run ends Mon 25 Aug; 26–31 draws as a shaded "after" zone.
32	
33	// The whole calendar day — the engine's summarize() still takes a start-time
34	// window, but the planner no longer exposes a start-time selector (it wasn't a
35	// useful whole-stack filter), so we always pass the full day and never filter
36	// on start time. Only the date window narrows the catchable set now.
37	const T_MIN = 0; // 00:00
38	const T_MAX = 1440; // 24:00
39	
40	const DEFAULT_D0 = 7; // default date window: Aug 7 → Aug 24 (the festival trip window)
41	const DEFAULT_D1 = 24;
42	
43	// Persist the uploaded favourites (as the raw slug list) in this browser so a
44	// returning visitor doesn't have to re-export/re-upload. We store slugs, not
45	// the matched show objects, so availability is always re-derived against the
46	// freshest catalogue on restore. Keyed with a version suffix so the shape can
47	// evolve without misreading an old record.
48	const STORAGE_KEY = "edfringe.plan.favourites.v1";
49	const TTL_MS = 3 * 24 * 60 * 60 * 1000; // keep for 3 days, then forget
50	
51	// --- Small helpers ------------------------------------------------------
52	
53	const $ = (id) => document.getElementById(id);
54	const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
55	const pad2 = (n) => String(n).padStart(2, "0");
56	
57	/** "YYYY-MM-DD" for a day-of-month within August 2026. */
58	function dateStr(day) {
59	  return `${YEAR}-${MONTH}-${pad2(day)}`;
60	}
61	
62	// 1 Aug 2026 is a Saturday; compute weekday letters from real dates rather
63	// than hardcoding, so this stays correct if the festival year ever changes.
64	const DOW_SHORT = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
65	function dowShort(day) {
66	  return DOW_SHORT[new Date(Date.UTC(YEAR, 7, day)).getUTCDay()];
67	}
68	function isWeekend(day) {
69	  const d = new Date(Date.UTC(YEAR, 7, day)).getUTCDay();
70	  return d === 0 || d === 6;
71	}
72	
73	// --- App state ------------------------------------------------------------
74	
75	const state = {
76	  index: null, // Map<slug, show> — the full catalogue
77	  matched: [], // full show objects for the user's matched favourites
78	  totalFavourites: 0,
79	  missingSlugs: [],
80	  filename: "",
81	  savedAt: null, // epoch ms the current set was uploaded/saved (drives the "from …" label)
82	  pendingUpload: null, // {slugs, filename, savedAt, scroll} retained so a failed load can retry it
83	  // Date window (drives summarize()'s filter):
84	  d0: DEFAULT_D0,
85	  d1: DEFAULT_D1,
86	  // Populated once per upload by buildCalendar():
87	  laneRefs: [], // [{ slug, el, statusEl }] in display (sorted) order
88	  layout: { trackLeft: 0, trackWidth: 0, dayW: 0 },
89	  dayHeaderBuilt: false,
90	};
91	
92	// --- Data loading -----------------------------------------------------
93	
94	// The show catalogue is a few MB and isn't needed until the user brings their
95	// favourites, so it loads in the background: the upload screen is usable right
96	// away, and we only make anyone wait (via ensureData) if they upload before the
97	// fetch lands. `dataPromise` resolves to state.index or rejects on failure.
98	let dataPromise = null;
99	
100	function loadData() {
101	  dataPromise = (async () => {
102	    const res = await fetch(DATA_URL);
103	    if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${DATA_URL}`);
104	    const shows = await res.json();
105	    state.index = buildIndex(shows);
106	    // Now the catalogue is available, re-hydrate any favourites saved from a
107	    // previous visit (fire-and-forget; a return visitor's calendar appears as
108	    // soon as the data lands, without ever blocking the upload screen).
109	    restoreStoredFavourites();
110	    return state.index;
111	  })();
112	  // Failures are surfaced at the await site (ensureData); swallow here so an
113	  // unconsumed background rejection doesn't log as "unhandled".
114	  dataPromise.catch(() => {});
115	  return dataPromise;
116	}
117	
118	// Resolve the catalogue for a consumer that actually needs it now. Shows the
119	// loading panel only if the background fetch is still in flight, so the user is
120	// never delayed unless their own action is waiting on the data.
121	async function ensureData() {
122	  if (state.index) return state.index;
123	  if (!dataPromise) loadData();
124	  $("errorState").hidden = true;
125	  $("loadingState").hidden = false;
126	  try {
127	    return await dataPromise;
128	  } catch (err) {
129	    dataPromise = null; // clear the rejected promise so the next attempt re-fetches
130	    throw err;
131	  } finally {
132	    $("loadingState").hidden = true;
133	  }
134	}
135	
136	// --- Local persistence (localStorage, 3-day TTL) --------------------------
137	
138	/** Persist the current favourite slugs so a return visit needn't re-upload. */
139	function saveFavourites(slugs, filename, savedAt) {
140	  try {
141	    localStorage.setItem(STORAGE_KEY, JSON.stringify({ v: 1, slugs, filename, savedAt }));
142	  } catch (err) {
143	    // Private mode / quota / disabled storage — persistence is a bonus, not
144	    // load-bearing, so swallow it and let the session run in-memory.
145	    console.warn("Fringe Planner: couldn't save favourites locally", err);
146	  }
147	}
148	
149	/**
150	 * Read the saved favourites, or null if there are none, they're malformed, or
151	 * they've aged past the TTL (expired/corrupt records are removed as a side
152	 * effect so we don't keep re-reading them).
153	 * @returns {{slugs: string[], filename: string, savedAt: number} | null}
154	 */
155	function loadStoredFavourites() {
156	  let raw = null;
157	  try {
158	    raw = localStorage.getItem(STORAGE_KEY);
159	  } catch (err) {
160	    console.warn("Fringe Planner: local storage unavailable", err);
161	    return null;
162	  }
163	  if (!raw) return null;
164	
165	  let data;
166	  try {
167	    data = JSON.parse(raw);
168	  } catch {
169	    clearStoredFavourites();
170	    return null;
171	  }
172	  if (!data || !Array.isArray(data.slugs) || typeof data.savedAt !== "number") {
173	    clearStoredFavourites();
174	    return null;
175	  }
176	  if (Date.now() - data.savedAt > TTL_MS) {
177	    clearStoredFavourites(); // stale — forget it
178	    return null;
179	  }
180	  return {
181	    slugs: data.slugs.filter((s) => typeof s === "string"),
182	    filename: typeof data.filename === "string" ? data.filename : "",
183	    savedAt: data.savedAt,
184	  };
185	}
186	
187	/** Remove the saved favourites from this browser. */
188	function clearStoredFavourites() {
189	  try {
190	    localStorage.removeItem(STORAGE_KEY);
191	  } catch (err) {
192	    console.warn("Fringe Planner: couldn't clear stored favourites", err);
193	  }
194	}
195	
196	/** On load, re-hydrate a still-valid saved set (no scroll — stay on screen 1). */
197	function restoreStoredFavourites() {
198	  const data = loadStoredFavourites();
199	  if (!data || data.slugs.length === 0) return;
200	  applyFavourites(data.slugs, data.filename, data.savedAt, { scroll: false });
201	}
202	
203	/** Wipe the current favourites from both the UI and storage. */
204	function clearFavourites() {
205	  clearStoredFavourites();
206	
207	  state.totalFavourites = 0;
208	  state.matched = [];
209	  state.missingSlugs = [];
210	  state.filename = "";
211	  state.savedAt = null;
212	
213	  $("summaryCap").hidden = true;
214	  const summaryEl = $("uploadSummary");
215	  summaryEl.hidden = true;
216	  summaryEl.classList.remove("is-partial");
217	  $("missingList").hidden = true;
218	  $("missingList").innerHTML = "";
219	  $("continueRow").hidden = true;
220	  $("savedBar").hidden = true;
221	  $("screen2").hidden = true;
222	
223	  $("screen1").scrollIntoView({ behavior: "smooth", block: "start" });
224	}
225	
226	// --- Screen 1: favourites intake -----------------------------------------
227	
228	/** Read a File via FileReader and hand its text to processFavouritesText. */
229	function handleFile(file) {
230	  if (!file) return;
231	  const reader = new FileReader();
232	  reader.onload = () => processFavouritesText(String(reader.result || ""), file.name);
233	  reader.onerror = () => {
234	    console.error("Fringe Planner: failed to read file", reader.error);
235	    alert("Couldn't read that file — please try again.");
236	  };
237	  reader.readAsText(file);
238	}
239	
240	/**
241	 * Parse a fresh upload, persist it (when it yielded any slugs), and render.
242	 * A file that parses to zero slugs leaves any previously saved set intact —
243	 * picking the wrong file shouldn't wipe a good saved list.
244	 */
245	function processFavouritesText(text, filename) {
246	  const slugs = parseFavourites(text);
247	  const savedAt = Date.now();
248	  if (slugs.length > 0) saveFavourites(slugs, filename, savedAt);
249	  applyFavourites(slugs, filename, savedAt, { scroll: true });
250	}
251	
252	/**
253	 * Match a slug list against the catalogue and render both screens. Shared by
254	 * fresh uploads (scroll to the calendar) and storage restores (stay put).
255	 */
256	async function applyFavourites(slugs, filename, savedAt, { scroll = false } = {}) {
257	  // Retained so the error state's "Try again" can re-run this exact set once
258	  // the catalogue fetch is retried.
259	  state.pendingUpload = { slugs, filename, savedAt, scroll };
260	
261	  // The catalogue is fetched in the background; wait for it now (only blocks if
262	  // it hasn't landed yet) before matching.
263	  let index;
264	  try {
265	    index = await ensureData();
266	  } catch (err) {
267	    console.error("Fringe Planner: failed to load show data", err);
268	    $("errorDetail").textContent =
269	      "Check your connection and try again. (" + (err && err.message ? err.message : "unknown error") + ")";
270	    $("errorState").hidden = false;
271	    return;
272	  }
273	
274	  const { matched, missingSlugs } = matchFavourites(slugs, index);
275	  state.pendingUpload = null;
276	
277	  state.totalFavourites = slugs.length;
278	  state.matched = matched;
279	  state.missingSlugs = missingSlugs;
280	  state.filename = filename;
281	  state.savedAt = savedAt;
282	
283	  renderUploadSummary();
284	  renderSavedBar();
285	
286	  if (matched.length > 0) {
287	    // Reset the window to the defaults on every fresh set.
288	    state.d0 = DEFAULT_D0;
289	    state.d1 = DEFAULT_D1;
290	    buildCalendar();
291	    showCalendar({ scroll });
292	  } else {
293	    $("screen2").hidden = true;
294	  }
295	}
296	
297	/** Day boundaries in local time; number of whole days from `a` to `b`. */
298	function dayDiff(a, b) {
299	  const da = Date.UTC(a.getFullYear(), a.getMonth(), a.getDate());
300	  const db = Date.UTC(b.getFullYear(), b.getMonth(), b.getDate());
301	  return Math.round((db - da) / 86400000);
302	}
303	
304	/** Friendly "when" for the saved-set label: today / yesterday / "18 Jul". */
305	function fmtSavedWhen(ts) {
306	  if (!ts) return "this session";
307	  const then = new Date(ts);
308	  const days = dayDiff(then, new Date());
309	  if (days <= 0) return "today";
310	  if (days === 1) return "yesterday";
311	  return then.toLocaleDateString("en-GB", { day: "numeric", month: "short" });
312	}
313	
314	/** The "N favourites from <when>" provenance line + Clear button visibility. */
315	function renderSavedBar() {
316	  const bar = $("savedBar");
317	  if (state.totalFavourites > 0) {
318	    const n = state.totalFavourites;
319	    $("savedNote").textContent =
320	      `${n} favourite${n === 1 ? "" : "s"} from ${fmtSavedWhen(state.savedAt)}`;
321	    bar.hidden = false;
322	  } else {
323	    bar.hidden = true;
324	  }
325	}
326	
327	function renderUploadSummary() {
328	  const { totalFavourites, matched, missingSlugs, filename } = state;
329	
330	  $("summaryCap").hidden = false;
331	  const summaryEl = $("uploadSummary");
332	  summaryEl.hidden = false;
333	  summaryEl.classList.toggle("is-partial", missingSlugs.length > 0);
334	
335	  $("usMain").textContent =
336	    totalFavourites === 0
337	      ? "No favourites found in that file"
338	      : `${totalFavourites} favourite${totalFavourites === 1 ? "" : "s"} loaded`;
339	
340	  if (totalFavourites === 0) {
341	    $("usSub").textContent = "We couldn't find any edfringe.com show links in that file.";
342	  } else {
343	    let sub = `${matched.length} matched to our show data`;
344	    if (missingSlugs.length > 0) {
345	      sub += ` · ${missingSlugs.length} we couldn't find `;
346	    }
347	    $("usSub").textContent = sub;
348	    if (missingSlugs.length > 0) {
349	      const whichBtn = document.createElement("button");
350	      whichBtn.type = "button";
351	      whichBtn.className = "link-quiet";
352	      whichBtn.textContent = "(which?)";
353	      whichBtn.addEventListener("click", toggleMissingList);
354	      $("usSub").appendChild(whichBtn);
355	    }
356	  }
357	  $("usFile").textContent = filename;
358	
359	  renderMissingList();
360	
361	  const continueRow = $("continueRow");
362	  continueRow.hidden = matched.length === 0;
363	  $("continueBtn").disabled = matched.length === 0;
364	}
365	
366	function renderMissingList() {
367	  const list = $("missingList");
368	  list.innerHTML = "";
369	  list.hidden = true;
370	  for (const slug of state.missingSlugs) {
371	    const li = document.createElement("li");
372	    const a = document.createElement("a");
373	    a.href = urlFromSlug(slug);
374	    a.target = "_blank";
375	    a.rel = "noopener";
376	    a.className = "link-quiet";
377	    a.innerHTML = `<code>${slug}</code>`;
378	    li.appendChild(a);
379	    list.appendChild(li);
380	  }
381	}
382	
383	function toggleMissingList() {
384	  const list = $("missingList");
385	  list.hidden = !list.hidden;
386	}
387	
388	/** Reveal the calendar panel; scroll to it only when the caller asks (fresh
389	 *  uploads and the Continue button do; a silent storage restore does not). */
390	function showCalendar({ scroll = false } = {}) {
391	  const screen2 = $("screen2");
392	  screen2.hidden = false;
393	  // Layout needs real geometry, which only exists once the panel is visible.
394	  requestAnimationFrame(() => layoutOverlay());
395	  if (scroll) screen2.scrollIntoView({ behavior: "smooth", block: "start" });
396	}
397	
398	// --- Screen 2: calendar ----------------------------------------------------
399	
400	/** Current summarize() filter derived from state.{d0,d1}. Start time is left
401	 *  wide open (00:00–24:00) — the planner filters on the date window only. */
402	function currentFilter() {
403	  return {
404	    dateStart: dateStr(state.d0),
405	    dateEnd: dateStr(state.d1),
406	    startTimeMin: T_MIN,
407	    startTimeMax: T_MAX,
408	  };
409	}
410	
411	/** Mode of a show's performance start times — used to order lanes morning → night. */
412	function typicalStartTime(performances) {
413	  const counts = new Map();
414	  for (const p of performances) counts.set(p.start, (counts.get(p.start) || 0) + 1);
415	  let best = null;
416	  let bestCount = -1;
417	  for (const [time, count] of counts) {
418	    if (count > bestCount || (count === bestCount && (best === null || time < best))) {
419	      best = time;
420	      bestCount = count;
421	    }
422	  }
423	  return best || "00:00";
424	}
425	
426	/** Build the static day-of-month header row (runs once; independent of data). */
427	function ensureDayHeader() {
428	  if (state.dayHeaderBuilt) return;
429	  const dayHead = $("dayHead");
430	  dayHead.innerHTML = "";
431	  for (let d = 1; d <= DAYS_IN_MONTH; d++) {
432	    const col = document.createElement("div");
433	    col.className = "day-col" + (isWeekend(d) ? " wknd" : "") + (d > FEST_END_DAY ? " post" : "");
434	    col.innerHTML = `<span class="day-dow">${dowShort(d)}</span><span class="day-num">${d}</span>`;
435	    dayHead.appendChild(col);
436	  }
437	  state.dayHeaderBuilt = true;
438	}
439	
440	/**
441	 * (Re)build the lanes from scratch: one row per matched favourite, sorted by
442	 * typical start time. Performance marks (filled/hollow/absent) are drawn from
443	 * `available`/`soldOut`, which don't depend on the date/time filter, so this
444	 * only needs to run once per upload — dragging the window only changes
445	 * per-lane verdicts (see applyVerdicts), not the marks themselves.
446	 */
447	function buildCalendar() {
448	  ensureDayHeader();
449	
450	  const filter = currentFilter();
451	  const result = summarize(state.matched, filter, state.totalFavourites);
452	  const bySlug = new Map(result.shows.map((s) => [s.slug, s]));
453	
454	  const ordered = [...result.shows].sort(
455	    (a, b) => typicalStartTime(a.performances).localeCompare(typicalStartTime(b.performances))
456	  );
457	
458	  const lanesEl = $("lanes");
459	  lanesEl.innerHTML = "";
460	  state.laneRefs = [];
461	
462	  for (const show of ordered) {
463	    const lane = document.createElement("div");
464	    lane.className = "cal-row lane";
465	    lane.dataset.slug = show.slug;
466	
467	    // Just the show title — this screen is an overview of the shows you want,
468	    // not a per-show detail card, so no time / genre / venue line.
469	    const label = document.createElement("div");
470	    label.className = "lane-label";
471	    label.title = show.title;
472	    label.innerHTML = `<div class="lane-title">${escapeHtml(show.title)}</div>`;
473	
474	    const track = document.createElement("div");
475	    track.className = "lane-track";
476	    track.appendChild(buildDayCells(show.performances));
477	
478	    const statusEl = document.createElement("div");
479	    statusEl.className = "lane-status";
480	
481	    lane.appendChild(label);
482	    lane.appendChild(track);
483	    lane.appendChild(statusEl);
484	    lanesEl.appendChild(lane);
485	
486	    state.laneRefs.push({ slug: show.slug, el: lane, statusEl });
487	  }
488	
489	  applyVerdicts(bySlug, filter);
490	  updateHero(result.counts, filter);
491	  layoutOverlay();
492	}
493	
494	// Map a performance to the edfringe.com day-picker colour class (CSS defines
495	// the actual hex — see plan.css). The status values come straight from
496	// shows.json; the palette mirrors edfringe.com's own availability legend.
497	function segClass(p) {
498	  if (p.soldOut) return "seg-sold";
499	  switch ((p.status || "").toUpperCase()) {
500	    case "TICKETS_AVAILABLE": return "seg-avail";
501	    case "TWO_FOR_ONE": return "seg-2for1";
502	    case "PREVIEW_SHOW": return "seg-preview";
503	    case "FREE_TICKETED":
504	    case "FREE_NON_TICKETED": return "seg-free";
505	    case "EVENT_SPECIFIC": return "seg-event";
506	    case "NO_ALLOCATION_CONTACT_VENUE": return "seg-noalloc";
507	    default: return p.available ? "seg-avail" : "seg-sold";
508	  }
509	}
510	
511	/** Human label for a performance's status, used in the day-cell tooltip. */
512	function statusLabel(p) {
513	  if (p.soldOut) return "sold out";
514	  switch ((p.status || "").toUpperCase()) {
515	    case "TICKETS_AVAILABLE": return "tickets available";
516	    case "TWO_FOR_ONE": return "2-for-1";
517	    case "PREVIEW_SHOW": return "preview";
518	    case "FREE_TICKETED": return "free (ticketed)";
519	    case "FREE_NON_TICKETED": return "free";
520	    case "EVENT_SPECIFIC": return "event-specific";
521	    case "NO_ALLOCATION_CONTACT_VENUE": return "no allocation — contact venue";
522	    default: return p.available ? "available" : "unavailable";
523	  }
524	}
525	
526	/**
527	 * Build the 31 day cells for one show. Each day with performances renders one
528	 * coloured segment per performance (colour = edfringe.com availability status),
529	 * so a day with two shows shows as two side-by-side segments — the split is the
530	 * graphical cue that there's more than one performance that day.
531	 */
532	function buildDayCells(performances) {
533	  const byDay = new Map(); // day-of-month -> performances that land on it
534	  for (const p of performances) {
535	    if (!p.date.startsWith(`${YEAR}-${MONTH}-`)) continue; // outside the Aug axis — see TODO above
536	    const day = Number(p.date.slice(8, 10));
537	    if (day < 1 || day > DAYS_IN_MONTH) continue;
538	    if (!byDay.has(day)) byDay.set(day, []);
539	    byDay.get(day).push(p);
540	  }
541	
542	  const frag = document.createDocumentFragment();
543	  for (let d = 1; d <= DAYS_IN_MONTH; d++) {
544	    const cell = document.createElement("span");
545	    cell.style.gridColumn = String(d);
546	    const entries = byDay.get(d);
547	    if (entries && entries.length > 0) {
548	      // Earliest performance first, so matinee/evening segments read left→right.
549	      entries.sort((a, b) => a.start.localeCompare(b.start));
550	      cell.className = "cell" + (entries.length > 1 ? " cell-multi" : "");
551	      for (const p of entries) {
552	        const seg = document.createElement("span");
553	        seg.className = "seg " + segClass(p);
554	        cell.appendChild(seg);
555	      }
556	      cell.title = entries
557	        .map((p) => `${dowShort(d)} ${d} Aug · ${p.start} · ${statusLabel(p)}`)
558	        .join("; ");
559	    }
560	    frag.appendChild(cell);
561	  }
562	  return frag;
563	}
564	
565	/** Escape untrusted show text before inserting via innerHTML. */
566	function escapeHtml(s) {
567	  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
568	}
569	
570	/**
571	 * Update each lane's dimmed/active state and right-hand verdict from a fresh
572	 * summarize() result — this is the cheap per-drag update (no DOM rebuild).
573	 */
574	function applyVerdicts(bySlug, filter) {
575	  for (const ref of state.laneRefs) {
576	    const show = bySlug.get(ref.slug);
577	    if (!show) continue;
578	    const { catchable, count } = laneVerdict(show.performances, filter);
579	    ref.el.classList.toggle("lane--out", !catchable);
580	    ref.statusEl.innerHTML = catchable
581	      ? `<span class="st-ok" title="${count} catchable date${count === 1 ? "" : "s"} in your window">&check;&nbsp;${count}</span>`
582	      : `<span class="st-no" title="nothing catchable in your window">&ndash;</span>`;
583	  }
584	}
585	
586	/** Catchable = at least one available performance inside the date window. */
587	function laneVerdict(performances, filter) {
588	  const availableInRange = performances.filter(
589	    (p) => p.available && p.date >= filter.dateStart && p.date <= filter.dateEnd
590	  );
591	  return availableInRange.length > 0
592	    ? { catchable: true, count: availableInRange.length }
593	    : { catchable: false, count: 0 };
594	}
595	
596	function updateHero(counts, filter) {
597	  const hcIn = $("hcIn");
598	  const changed = hcIn.textContent !== String(counts.showsAvailableInWindow);
599	  hcIn.textContent = counts.showsAvailableInWindow;
600	  $("hcAll").textContent = counts.matchedShows;
601	  $("hcDetail").textContent = `${state.d0}–${state.d1} Aug`;
602	  if (changed) {
603	    const num = hcIn.closest(".hc-num");
604	    num.classList.remove("bump");
605	    void num.offsetWidth; // restart the CSS animation
606	    num.classList.add("bump");
607	  }
608	}
609	
610	/** rAF-throttled: re-summarize + re-render verdicts, coalesced to once per frame. */
611	let recomputeScheduled = false;
612	function scheduleRecompute() {
613	  if (recomputeScheduled) return;
614	  recomputeScheduled = true;
615	  requestAnimationFrame(() => {
616	    recomputeScheduled = false;
617	    recomputeAndRender();
618	  });
619	}
620	function recomputeAndRender() {
621	  const filter = currentFilter();
622	  const result = summarize(state.matched, filter, state.totalFavourites);
623	  const bySlug = new Map(result.shows.map((s) => [s.slug, s]));
624	  applyVerdicts(bySlug, filter);
625	  updateHero(result.counts, filter);
626	}
627	
628	// --- Window overlay geometry & date-window dragging ------------------------
629	
630	const calWrap = () => $("calWrap");
631	const calInner = () => $("calInner");
632	
633	function layoutOverlay() {
634	  const daysEl = $("dayHead");
635	  const dr = daysEl.getBoundingClientRect();
636	  if (dr.width === 0) return; // panel not visible yet
637	  const wr = calInner().getBoundingClientRect();
638	  const trackLeft = dr.left - wr.left;
639	  const trackWidth = dr.width;
640	  const dayW = trackWidth / DAYS_IN_MONTH;
641	  state.layout = { trackLeft, trackWidth, dayW };
642	
643	  const win = $("win");
644	  win.style.left = trackLeft + "px";
645	  win.style.width = trackWidth + "px";
646	
647	  const festEnd = $("festEnd");
648	  festEnd.style.left = trackLeft + FEST_END_DAY * dayW + "px";
649	  festEnd.style.width = (DAYS_IN_MONTH - FEST_END_DAY) * dayW + "px";
650	
651	  paintWindow();
652	}
653	
654	function paintWindow() {
655	  const { trackWidth, dayW } = state.layout;
656	  const x0 = (state.d0 - 1) * dayW;
657	  const x1 = state.d1 * dayW;
658	  $("dimL").style.left = "0";
659	  $("dimL").style.width = x0 + "px";
660	  $("dimR").style.left = x1 + "px";
661	  $("dimR").style.width = Math.max(0, trackWidth - x1) + "px";
662	  $("band").style.left = x0 + "px";
663	  $("band").style.width = (x1 - x0) + "px";
664	  $("hStart").style.left = x0 + "px";
665	  $("hEnd").style.left = x1 + "px";
666	  $("flagStart").textContent = `${state.d0} Aug`;
667	  $("flagEnd").textContent = `${state.d1} Aug`;
668	  const hStart = $("hStart");
669	  hStart.setAttribute("aria-valuenow", state.d0);
670	  hStart.setAttribute("aria-valuetext", `${state.d0} August`);
671	  const hEnd = $("hEnd");
672	  hEnd.setAttribute("aria-valuenow", state.d1);
673	  hEnd.setAttribute("aria-valuetext", `${state.d1} August`);
674	}
675	
676	function dayAt(clientX) {
677	  const wr = calInner().getBoundingClientRect();
678	  const { trackLeft, dayW } = state.layout;
679	  return clamp(Math.round((clientX - wr.left - trackLeft) / dayW), 0, DAYS_IN_MONTH);
680	}
681	
682	/** Wire pointer-drag on a date handle/band; `apply` mutates state.d0/d1 per move. */
683	function dragDate(el, apply) {
684	  el.addEventListener("pointerdown", (e) => {
685	    e.preventDefault();
686	    el.setPointerCapture(e.pointerId);
687	    const startX = e.clientX;
688	    const s0 = state.d0;
689	    const s1 = state.d1;
690	    const move = (ev) => {
691	      apply(ev, s0, s1, startX);
692	      paintWindow();
693	      scheduleRecompute();
694	    };
695	    const up = () => {
696	      el.removeEventListener("pointermove", move);
697	      el.removeEventListener("pointerup", up);
698	    };
699	    el.addEventListener("pointermove", move);
700	    el.addEventListener("pointerup", up);
701	  });
702	}
703	
704	function keysDate(el, fn) {
705	  el.addEventListener("keydown", (e) => {
706	    const dd = e.key === "ArrowLeft" ? -1 : e.key === "ArrowRight" ? 1 : 0;
707	    if (!dd) return;
708	    e.preventDefault();
709	    fn(dd);
710	    paintWindow();
711	    scheduleRecompute();
712	  });
713	}
714	
715	// --- Wiring -----------------------------------------------------------
716	
717	function wireDropzone() {
718	  const dz = $("dropzone");
719	  const input = $("csvInput");
720	
721	  input.addEventListener("change", () => {
722	    if (input.files && input.files[0]) handleFile(input.files[0]);
723	    input.value = ""; // allow re-selecting the same filename later
724	  });
725	
726	  ["dragenter", "dragover"].forEach((evt) =>
727	    dz.addEventListener(evt, (e) => {
728	      e.preventDefault();
729	      dz.classList.add("is-dragover");
730	    })
731	  );
732	  ["dragleave", "dragend"].forEach((evt) =>
733	    dz.addEventListener(evt, () => dz.classList.remove("is-dragover"))
734	  );
735	  dz.addEventListener("drop", (e) => {
736	    e.preventDefault();
737	    dz.classList.remove("is-dragover");
738	    const file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
739	    if (file) handleFile(file);
740	  });
741	}
742	
743	function wireSampleLink() {
744	  $("sampleLink").addEventListener("click", async (e) => {
745	    e.preventDefault();
746	    try {
747	      const res = await fetch(SAMPLE_URL);
748	      if (!res.ok) throw new Error(`HTTP ${res.status}`);
749	      const text = await res.text();
750	      processFavouritesText(text, "sample-favourites.csv");
751	    } catch (err) {
752	      console.error("Fringe Planner: failed to load sample favourites", err);
753	      alert("Couldn't load the sample favourites — please try uploading a file instead.");
754	    }
755	  });
756	}
757	
758	function wireContinueButton() {
759	  $("continueBtn").addEventListener("click", () => {
760	    if (state.matched.length > 0) showCalendar({ scroll: true });
761	  });
762	}
763	
764	function wireClearButton() {
765	  $("clearFavBtn").addEventListener("click", clearFavourites);
766	}
767	
768	function wireRetry() {
769	  $("retryBtn").addEventListener("click", () => {
770	    $("errorState").hidden = true;
771	    loadData(); // fresh fetch, replacing the rejected promise
772	    if (state.pendingUpload) {
773	      // Re-run the set the user was waiting on; ensureData awaits the retry.
774	      const { slugs, filename, savedAt, scroll } = state.pendingUpload;
775	      applyFavourites(slugs, filename, savedAt, { scroll });
776	    }
777	  });
778	}
779	
780	function wireCalendarControls() {
781	  dragDate($("hStart"), (ev) => {
782	    state.d0 = clamp(dayAt(ev.clientX) + 1, 1, state.d1);
783	  });
784	  dragDate($("hEnd"), (ev) => {
785	    state.d1 = clamp(dayAt(ev.clientX), state.d0, DAYS_IN_MONTH);
786	  });
787	  dragDate($("band"), (ev, s0, s1, startX) => {
788	    const { dayW } = state.layout;
789	    const dd = Math.round((ev.clientX - startX) / dayW);
790	    const len = s1 - s0;
791	    state.d0 = clamp(s0 + dd, 1, DAYS_IN_MONTH - len);
792	    state.d1 = state.d0 + len;
793	  });
794	  keysDate($("hStart"), (dd) => {
795	    state.d0 = clamp(state.d0 + dd, 1, state.d1);
796	  });
797	  keysDate($("hEnd"), (dd) => {
798	    state.d1 = clamp(state.d1 + dd, state.d0, DAYS_IN_MONTH);
799	  });
800	
801	  window.addEventListener("resize", () => layoutOverlay());
802	}
803	
804	// --- Go ---------------------------------------------------------------
805	
806	wireDropzone();
807	wireSampleLink();
808	wireContinueButton();
809	wireClearButton();
810	wireRetry();
811	wireCalendarControls();
812	
813	// The upload screen is visible from first paint; fetch the catalogue in the
814	// background so the user can read the instructions and export their CSV while it
815	// loads, and only waits (if at all) at the moment they actually upload.
816	loadData();
817

