1	/* Fringe Planner — stylesheet
2	 * Extracted/adapted from plan/design/mock.html. Brand tokens match the home
3	 * site's css/styles.css (violet #6c4cf1, ink/muted/hairline, 16px radius,
4	 * soft shadow, Plus Jakarta Sans display + Inter body, 1120px container).
5	 * This stylesheet is self-contained — the planner does not load styles.css.
6	 */
7	
8	:root {
9	  --violet: #6c4cf1;
10	  --violet-dark: #5a3fd6;
11	  --ink: #101828;
12	  --paper: #ffffff;
13	  --bg: #f7f8fa;
14	  --muted: #667085;
15	  --line: #eaecf0;
16	  --ok: #059669;
17	  --ok-text: #047857;
18	  --ok-bg: #e6f7ee;
19	  --warn: #ef4444;
20	  /* Performance-date availability palette — taken from edfringe.com's own
21	     ticket day-picker legend so the calendar reads the same as the official
22	     site. Violet stays reserved for the date-window instrument + chrome. */
23	  --fr-avail: #2ac9de;    /* tickets available */
24	  --fr-2for1: #ffce00;    /* 2-for-1 */
25	  --fr-preview: #3438ff;  /* preview show */
26	  --fr-free: #00bf57;     /* free (ticketed / non-ticketed) */
27	  --fr-event: #8c4fd9;    /* event-specific */
28	  --fr-noalloc: #ef3934;  /* no allocation — contact venue */
29	  --fr-sold-bg: #e6e9ef;  /* sold out — greyed, as the official picker disables it */
30	  --fr-sold-line: #c6cdda;
31	  --fr-ink: #00243d;      /* edfringe.com ink */
32	  --shadow-soft: 0 12px 30px rgba(16, 24, 40, 0.08);
33	  --maxw: 1120px;
34	  --radius: 16px;
35	  --sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
36	  --display: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;
37	}
38	* { box-sizing: border-box; }
39	html { scroll-behavior: smooth; }
40	body {
41	  margin: 0;
42	  font-family: var(--sans);
43	  color: var(--ink);
44	  background: var(--bg);
45	  line-height: 1.5;
46	}
47	[hidden] { display: none !important; }
48	.container { width: 100%; max-width: var(--maxw); margin: 0 auto; padding-inline: 24px; }
49	a { color: inherit; }
50	.sr-only {
51	  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
52	  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
53	}
54	
55	/* ============ Header ============ */
56	.site-header {
57	  border-bottom: 1px solid var(--line);
