62	.header-inner { display: flex; align-items: center; height: 64px; gap: 24px; }
63	.logo {
64	  font-family: var(--display); font-weight: 700; font-size: 1.4rem;
65	  letter-spacing: -0.01em; text-decoration: none; white-space: nowrap;
66	}
67	.logo-now { color: var(--violet); }
68	.main-nav { display: flex; gap: 28px; margin-inline: auto; }
69	.nav-link {
70	  text-decoration: none; font-size: 0.98rem; padding-bottom: 2px;
71	  border-bottom: 2px solid transparent; color: var(--ink);
72	}
73	.nav-link:hover { color: var(--violet); }
74	.nav-link.is-active { color: var(--violet); border-bottom-color: var(--violet); }
75	.header-hint { font-size: 0.8rem; color: var(--muted); white-space: nowrap; }
76	
77	/* ============ Page head ============ */
78	.page-head { padding: 44px 0 8px; }
79	.page-kicker {
80	  display: inline-block; font-size: 0.72rem; font-weight: 700;
81	  letter-spacing: 0.08em; text-transform: uppercase; color: var(--violet);
82	  background: rgba(108, 76, 241, 0.09); border-radius: 999px; padding: 5px 12px;
83	  margin: 0 0 12px;
84	}
85	.page-title {
86	  font-family: var(--display); font-weight: 700; letter-spacing: -0.01em;
87	  font-size: 2.3rem; line-height: 1.12; margin: 0 0 8px;
88	}
89	.page-sub { color: var(--muted); font-size: 1.02rem; max-width: 640px; margin: 0; }
90	
91	.panel {
92	  background: var(--paper);
93	  border: 1px solid var(--line);
94	  border-radius: var(--radius);
95	  box-shadow: var(--shadow-soft);
96	}
97	
98	/* ============ Loading / error states ============ */
99	.state-panel {
100	  max-width: 660px; margin: 40px auto; padding: 40px 32px;
101	  text-align: center; border-radius: var(--radius);
