110	.state-title { font-family: var(--display); font-weight: 700; font-size: 1.15rem; margin: 0 0 6px; }
111	.state-sub { color: var(--muted); font-size: 0.92rem; margin: 0; }
112	.state-error .state-icon {
113	  width: 44px; height: 44px; margin: 0 auto 14px; border-radius: 50%;
114	  display: grid; place-items: center; color: var(--warn); background: rgba(239, 68, 68, 0.1);
115	}
116	.state-error .btn { margin-top: 16px; }
117	
118	/* ============ Screen 1 — Input ============ */
119	.intake { max-width: 660px; margin: 0 auto; padding: 36px 40px 30px; }
120	.step-kicker {
121	  font-size: 0.72rem; font-weight: 700; letter-spacing: 0.08em;
122	  text-transform: uppercase; color: var(--violet); margin: 0 0 6px;
123	}
124	.intake-title {
125	  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
126	  letter-spacing: -0.01em; margin: 0 0 6px;
127	}
128	.intake-sub { color: var(--muted); font-size: 0.95rem; margin: 0 0 22px; }
129	.intake-sub .crumbs { color: var(--ink); font-weight: 600; white-space: nowrap; }
130	.intake-sub .crumb-sep { color: #b6bdc9; padding-inline: 2px; }
131	
132	.dropzone {
133	  display: flex; flex-direction: column; align-items: center; gap: 6px;
134	  text-align: center; padding: 34px 24px 30px;
135	  border: 2px dashed #d5d9e2; border-radius: var(--radius);
136	  background: #fbfbfd;
137	  transition: border-color 0.15s ease, background 0.15s ease;
138	  cursor: pointer;
139	}
140	.dropzone:hover, .dropzone:focus-within, .dropzone.is-dragover {
141	  border-color: var(--violet); background: rgba(108, 76, 241, 0.04);
142	}
143	.dz-icon {
144	  width: 46px; height: 46px; display: grid; place-items: center;
145	  color: var(--violet); background: rgba(108, 76, 241, 0.1);
146	  border-radius: 14px; margin-bottom: 6px;
147	}
148	.dz-line1 { font-weight: 700; font-size: 1.02rem; }
149	.dz-line2 { color: var(--muted); font-size: 0.85rem; margin-bottom: 12px; }
150	.btn {
151	  display: inline-flex; align-items: center; gap: 8px;
152	  font: inherit; font-weight: 700; font-size: 0.95rem;
153	  border: none; border-radius: 12px; padding: 12px 22px; cursor: pointer;
154	  color: #fff; background: var(--violet);
155	  box-shadow: 0 8px 20px rgba(108, 76, 241, 0.28);
156	  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
157	  text-decoration: none;
158	}
159	.btn:hover { background: var(--violet-dark); transform: translateY(-1px); }
160	.btn:focus-visible { outline: 3px solid var(--violet); outline-offset: 3px; }
161	.btn:disabled { opacity: 0.55; cursor: not-allowed; transform: none; }
162	.dz-alt { margin-top: 12px; font-size: 0.85rem; color: var(--muted); }
163	.link-quiet {
164	  font-weight: 700; color: var(--violet-dark); text-decoration: none;
165	  border-bottom: 1px solid rgba(108, 76, 241, 0.35);
166	  background: none; border-top: none; border-left: none; border-right: none;
167	  font: inherit; cursor: pointer; padding: 0;
168	}
169	.link-quiet:hover { color: var(--violet); border-bottom-color: var(--violet); }
170	
171	/* Upload summary */
172	.statecap {
173	  margin: 22px 0 8px; font-size: 0.64rem; font-weight: 700;
174	  letter-spacing: 0.1em; text-transform: uppercase; color: #98a2b3;
175	}
176	.upload-summary {
177	  display: flex; align-items: center; gap: 14px;
178	  border: 1px solid #c7ecd9; background: var(--ok-bg);
179	  border-radius: 12px; padding: 13px 16px;
180	}
181	.upload-summary.is-partial { border-color: #fde3b8; background: #fff8ea; }
182	.us-tick {
183	  flex: 0 0 auto; width: 30px; height: 30px; border-radius: 50%;
184	  display: grid; place-items: center; color: #fff; background: var(--ok);
185	}
186	.us-body { flex: 1; min-width: 0; }
187	.us-main { font-weight: 700; font-size: 0.95rem; color: var(--ok-text); }
188	.us-sub { font-size: 0.8rem; color: var(--muted); }
189	.us-file {
190	  flex: 0 0 auto; font-size: 0.74rem; font-weight: 600; color: var(--muted);
191	  background: #fff; border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px;
192	  white-space: nowrap;
193	}
194	/* Saved-favourites provenance bar + clear control */
195	.saved-bar {
196	  display: flex; align-items: center; justify-content: space-between; gap: 12px;
197	  flex-wrap: wrap; margin-top: 10px; padding: 8px 14px;
198	  border: 1px solid var(--line); border-radius: 10px; background: #fff;
199	}
200	.saved-note {
201	  display: inline-flex; align-items: center; gap: 7px;
202	  font-size: 0.82rem; font-weight: 600; color: var(--ink); min-width: 0;
203	}
204	.saved-ico { flex: 0 0 auto; color: var(--violet); }
205	.saved-hint { font-weight: 400; color: var(--muted); }
206	
207	.missing-list {
208	  margin: 8px 0 0; padding: 10px 14px; list-style: none;
209	  border: 1px solid var(--line); border-radius: 10px; background: #fff;
210	  font-size: 0.82rem; color: var(--muted); max-height: 160px; overflow-y: auto;
211	}
212	.missing-list li { padding: 2px 0; }
213	.missing-list code { font-size: 0.8rem; color: var(--ink); }
214	
215	.continue-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 18px; flex-wrap: wrap; }
216	.continue-note { font-size: 0.82rem; color: var(--muted); }
217	
218	/* Collapsed "More settings" placeholder */
219	.more { margin-top: 22px; border-top: 1px solid var(--line); padding-top: 6px; }
220	.more summary {
221	  display: flex; align-items: center; gap: 8px; list-style: none;
222	  cursor: pointer; padding: 10px 4px; font-weight: 700; font-size: 0.9rem; color: var(--ink);
223	  border-radius: 8px;
224	}
225	.more summary::-webkit-details-marker { display: none; }
226	.more summary:hover { color: var(--violet-dark); }
227	.more summary:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
228	.more-caret { transition: transform 0.15s ease; color: var(--muted); font-size: 0.7rem; }
229	.more[open] .more-caret { transform: rotate(180deg); }
230	.more-hint { margin-left: auto; font-weight: 600; font-size: 0.74rem; color: #98a2b3; }
231	.more-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 22px; padding: 8px 4px 14px; }
232	.more-field-label {
233	  display: block; text-transform: uppercase; letter-spacing: 0.05em;
234	  font-size: 0.68rem; font-weight: 700; color: var(--muted); margin: 0 0 7px;
235	}
236	.chips { display: flex; flex-wrap: wrap; gap: 6px; grid-column: 1 / -1; }
237	.chips-wrap { grid-column: 1 / -1; }
238	.chip {
239	  font-size: 0.78rem; font-weight: 600; padding: 6px 12px; border-radius: 999px;
240	  border: 1px solid var(--line); background: #fff; color: var(--muted);
241	}
242	.chip.is-on { border-color: var(--violet); color: var(--violet-dark); background: rgba(108, 76, 241, 0.07); }
243	.faux-input {
244	  display: flex; align-items: center; justify-content: space-between; gap: 8px;
245	  font-size: 0.88rem; font-weight: 600;
246	  border: 1px solid var(--line); border-radius: 10px; background: #fff;
247	  padding: 9px 12px; color: var(--ink);
248	}
249	.faux-input .fi-caret { color: var(--muted); font-size: 0.68rem; }
250	
251	/* ============ Screen 2 — Availability calendar ============ */
252	.cal-card { padding: 30px 28px 26px; }
253	.cal-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 28px; flex-wrap: wrap; }
254	.cal-title {
255	  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
256	  letter-spacing: -0.01em; margin: 0 0 6px;
257	}
258	.cal-sub { color: var(--muted); font-size: 0.92rem; margin: 0; max-width: 520px; }
259	
260	/* The payoff number */
261	.hero-count { text-align: right; flex: 0 0 auto; }
262	.hc-num {
263	  font-weight: 800; font-size: 3.1rem; line-height: 1; letter-spacing: -0.02em;
264	  color: var(--violet-dark); white-space: nowrap;
265	}
266	.hc-num .hc-of { color: #b7bcc9; font-weight: 700; font-size: 2rem; }
267	.hc-num.bump { animation: countbump 0.4s ease; }
268	@keyframes countbump {
269	  0% { transform: scale(1); }
270	  45% { transform: scale(1.09); color: var(--violet); }
271	  100% { transform: scale(1); }
272	}
273	.hc-label { font-size: 0.84rem; font-weight: 600; color: var(--ink); margin-top: 2px; }
274	.hc-detail { font-size: 0.78rem; color: var(--muted); font-variant-numeric: tabular-nums; }
275	
276	/* Toolbar: the availability legend. Colours mirror edfringe.com's own
277	   day-picker legend (see plan.js segClass / the --fr-* tokens below). */
278	.cal-toolbar {
279	  display: flex; align-items: center; gap: 14px 20px;
280	  margin: 22px 0 6px; padding-top: 18px; border-top: 1px solid var(--line);
281	  flex-wrap: wrap;
282	}
283	.legend { display: flex; gap: 10px 16px; flex-wrap: wrap; }
284	.lg { display: inline-flex; align-items: center; gap: 7px; font-size: 0.76rem; color: var(--muted); }
285	.lg i { width: 14px; height: 11px; border-radius: 3px; display: block; }
286	.lg-avail i   { background: var(--fr-avail); }
287	.lg-2for1 i   { background: var(--fr-2for1); }
288	.lg-preview i { background: var(--fr-preview); }
289	.lg-free i    { background: var(--fr-free); }
290	.lg-event i   { background: var(--fr-event); }
291	.lg-noalloc i { background: var(--fr-noalloc); }
292	.lg-sold i    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }
293	/* A miniature two-segment cell, matching the split used in the calendar. */
294	.lg-multi i.multi { display: inline-flex; gap: 1.5px; background: none; width: 16px; }
295	.lg-multi i.multi b { flex: 1; border-radius: 2px; }
296	.lg-multi i.multi b:first-child { background: var(--fr-avail); }
297	.lg-multi i.multi b:last-child { background: var(--fr-2for1); }
298	
299	/* --- The calendar canvas --- */
300	/* .cal-wrap is the scroll container: day-header stays sticky at its top while
301	   the lane list scrolls beneath it. The toolbar/hero-count above are outside
302	   this container entirely, so they never scroll away either. */
303	.cal-wrap {
304	  position: relative; margin-top: 14px;
305	  max-height: 62vh; overflow-y: auto; overflow-x: hidden;
306	  border-radius: 10px;
307	}
308	.cal-inner { position: relative; padding-top: 40px; /* room for the handle flags */ }
309	
310	.cal-row { display: grid; grid-template-columns: 190px 1fr 52px; gap: 0 14px; align-items: center; }
311	
312	.cal-head {
313	  border-bottom: 1px solid var(--line); padding-bottom: 6px;
314	  position: sticky; top: 0; z-index: 4; background: var(--paper);
315	}
316	.cal-head-left { font-size: 0.72rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--muted); }
317	.cal-head-right { font-size: 0.62rem; font-weight: 600; color: #98a2b3; text-align: center; line-height: 1.15; }
318	.days { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; }
319	.day-col { text-align: center; line-height: 1.15; }
320	.day-dow { display: block; font-size: 0.56rem; font-weight: 600; color: #b0b7c3; }
321	.day-num { display: block; font-size: 0.7rem; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
322	.day-col.wknd .day-num { color: var(--ink); font-weight: 700; }
323	.day-col.post .day-num, .day-col.post .day-dow { color: #cfd4de; }
324	
325	.lanes { position: relative; z-index: 1; }
326	/* One tight single-line row per show — this screen is an overview of the shows
327	   you want, so each row is deliberately compact (title only, no meta line). */
328	.lane { min-height: 22px; padding: 1px 0; border-bottom: 1px solid #f1f2f6; }
329	.lane:last-child { border-bottom: none; }
330	.lane-label { min-width: 0; }
331	.lane-title {
332	  font-family: var(--display); font-weight: 600; font-size: 0.8rem; line-height: 1.2;
333	  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
334	}
335	.lane-track { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; align-items: center; height: 100%; }
336	
337	/* A day cell holds one coloured segment per performance; two performances on a
338	   day render as two side-by-side segments — the split IS the "two shows that
339	   day" cue. Single-performance days read as one solid bar. */
340	.cell { height: 10px; border-radius: 3px; display: flex; gap: 0; overflow: hidden; }
341	.cell-multi { gap: 1.5px; }
342	.seg { flex: 1 1 0; min-width: 0; border-radius: 3px; }
343	.seg-avail   { background: var(--fr-avail); }
344	.seg-2for1   { background: var(--fr-2for1); }
345	.seg-preview { background: var(--fr-preview); }
346	.seg-free    { background: var(--fr-free); }
347	.seg-event   { background: var(--fr-event); }
348	.seg-noalloc { background: var(--fr-noalloc); }
349	.seg-sold    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }
350	
351	.lane-status { font-size: 0.78rem; line-height: 1.2; text-align: center; }
352	.lane-status .st-ok { font-weight: 700; color: var(--ok-text); font-variant-numeric: tabular-nums; }
353	.lane-status .st-no { color: #c2c8d2; font-weight: 700; }
354	/* A show with nothing catchable in the window recedes as a whole. */
355	.lane--out .lane-title { opacity: 0.42; }
356	.lane--out .lane-track { opacity: 0.35; }
357	
358	/* --- Window overlay: dim panels, highlight band, drag handles --- */
359	.win { position: absolute; top: 0; bottom: 0; z-index: 2; pointer-events: none; }
360	.festend { position: absolute; top: 40px; bottom: 0; background: rgba(234, 236, 240, 0.35); border-left: 1px dashed #d5d9e2; pointer-events: none; z-index: 1; }
361	.win-dim { position: absolute; top: 40px; bottom: 0; background: rgba(247, 248, 250, 0.72); }
362	.win-band {
363	  position: absolute; top: 40px; bottom: 0;
364	  background: rgba(108, 76, 241, 0.05);
365	  border-left: 2px solid var(--violet); border-right: 2px solid var(--violet);
366	  cursor: grab; pointer-events: auto; touch-action: none;
367	}
368	.win-band:active { cursor: grabbing; }
369	.win-handle {
370	  position: absolute; top: 0; bottom: 0; width: 26px;
371	  transform: translateX(-50%);
372	  pointer-events: auto; cursor: ew-resize; touch-action: none;
373	}
374	/* Flags anchor OUTWARD from their line (start points left, end points right),
375	   so they never collide even when the window is dragged narrow. */
376	.win-flag {
377	  position: absolute; top: 2px;
378	  display: inline-flex; align-items: center; gap: 6px;
379	  font-size: 0.72rem; font-weight: 700; color: var(--violet-dark);
380	  background: #fff; border: 1.5px solid var(--violet); border-radius: 999px;
381	  padding: 4px 11px; white-space: nowrap;
382	  box-shadow: 0 3px 10px rgba(16, 24, 40, 0.12);
383	  font-variant-numeric: tabular-nums;
384	}
385	.win-handle--start .win-flag { right: 50%; margin-right: -2px; }
386	.win-handle--end .win-flag { left: 50%; margin-left: -2px; }
387	.win-flag .grip { display: inline-flex; gap: 2px; }
388	.win-flag .grip i { width: 2.5px; height: 9px; border-radius: 2px; background: rgba(108, 76, 241, 0.5); display: block; }
389	.win-handle:hover .win-flag, .win-handle:focus-visible .win-flag {
390	  background: var(--violet); color: #fff; border-color: var(--violet);
391	}
392	.win-handle:hover .win-flag .grip i, .win-handle:focus-visible .win-flag .grip i { background: rgba(255, 255, 255, 0.75); }
393	.win-handle:focus-visible { outline: none; }
394	.win-handle:focus-visible .win-flag { box-shadow: 0 0 0 3px rgba(108, 76, 241, 0.35); }
395	
396	.cal-foot {
397	  display: flex; justify-content: space-between; gap: 20px;
398	  margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line);
399	  font-size: 0.78rem; color: var(--muted); flex-wrap: wrap;
400	}
401	
402	/* ============ Footer ============ */
403	.site-footer { background: var(--ink); color: #d9d9d9; padding: 28px 0; margin-top: 56px; }
404	.footer-inner { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
405	.footer-copy { color: #8c8c8c; font-size: 0.85rem; }
406	
407	@media (prefers-reduced-motion: reduce) {
408	  .hc-num.bump { animation: none; }
409	  html { scroll-behavior: auto; }
410	}
411

file.content:
/* Fringe Planner — stylesheet
 * Extracted/adapted from plan/design/mock.html. Brand tokens match the home
 * site's css/styles.css (violet #6c4cf1, ink/muted/hairline, 16px radius,
 * soft shadow, Plus Jakarta Sans display + Inter body, 1120px container).
 * This stylesheet is self-contained — the planner does not load styles.css.
 */

:root {
  --violet: #6c4cf1;
  --violet-dark: #5a3fd6;
  --ink: #101828;
  --paper: #ffffff;
  --bg: #f7f8fa;
  --muted: #667085;
  --line: #eaecf0;
  --ok: #059669;
  --ok-text: #047857;
  --ok-bg: #e6f7ee;
  --warn: #ef4444;
  /* Performance-date availability palette — taken from edfringe.com's own
     ticket day-picker legend so the calendar reads the same as the official
     site. Violet stays reserved for the date-window instrument + chrome. */
  --fr-avail: #2ac9de;    /* tickets available */
  --fr-2for1: #ffce00;    /* 2-for-1 */
  --fr-preview: #3438ff;  /* preview show */
  --fr-free: #00bf57;     /* free (ticketed / non-ticketed) */
  --fr-event: #8c4fd9;    /* event-specific */
  --fr-noalloc: #ef3934;  /* no allocation — contact venue */
  --fr-sold-bg: #e6e9ef;  /* sold out — greyed, as the official picker disables it */
  --fr-sold-line: #c6cdda;
  --fr-ink: #00243d;      /* edfringe.com ink */
  --shadow-soft: 0 12px 30px rgba(16, 24, 40, 0.08);
  --maxw: 1120px;
  --radius: 16px;
  --sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --display: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--sans);
  color: var(--ink);
  background: var(--bg);
  line-height: 1.5;
}
[hidden] { display: none !important; }
.container { width: 100%; max-width: var(--maxw); margin: 0 auto; padding-inline: 24px; }
a { color: inherit; }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

/* ============ Header ============ */
.site-header {
  border-bottom: 1px solid var(--line);
  position: sticky; top: 0; z-index: 50;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(6px);
}
.header-inner { display: flex; align-items: center; height: 64px; gap: 24px; }
.logo {
  font-family: var(--display); font-weight: 700; font-size: 1.4rem;
  letter-spacing: -0.01em; text-decoration: none; white-space: nowrap;
}
.logo-now { color: var(--violet); }
.main-nav { display: flex; gap: 28px; margin-inline: auto; }
.nav-link {
  text-decoration: none; font-size: 0.98rem; padding-bottom: 2px;
  border-bottom: 2px solid transparent; color: var(--ink);
}
.nav-link:hover { color: var(--violet); }
.nav-link.is-active { color: var(--violet); border-bottom-color: var(--violet); }
.header-hint { font-size: 0.8rem; color: var(--muted); white-space: nowrap; }

/* ============ Page head ============ */
.page-head { padding: 44px 0 8px; }
.page-kicker {
  display: inline-block; font-size: 0.72rem; font-weight: 700;
  letter-spacing: 0.08em; text-transform: uppercase; color: var(--violet);
  background: rgba(108, 76, 241, 0.09); border-radius: 999px; padding: 5px 12px;
  margin: 0 0 12px;
}
.page-title {
  font-family: var(--display); font-weight: 700; letter-spacing: -0.01em;
  font-size: 2.3rem; line-height: 1.12; margin: 0 0 8px;
}
.page-sub { color: var(--muted); font-size: 1.02rem; max-width: 640px; margin: 0; }

.panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow-soft);
}

/* ============ Loading / error states ============ */
.state-panel {
  max-width: 660px; margin: 40px auto; padding: 40px 32px;
  text-align: center; border-radius: var(--radius);
  background: var(--paper); border: 1px solid var(--line); box-shadow: var(--shadow-soft);
}
.state-spinner {
  width: 34px; height: 34px; margin: 0 auto 16px; border-radius: 50%;
  border: 3px solid var(--line); border-top-color: var(--violet);
  animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
.state-title { font-family: var(--display); font-weight: 700; font-size: 1.15rem; margin: 0 0 6px; }
.state-sub { color: var(--muted); font-size: 0.92rem; margin: 0; }
.state-error .state-icon {
  width: 44px; height: 44px; margin: 0 auto 14px; border-radius: 50%;
  display: grid; place-items: center; color: var(--warn); background: rgba(239, 68, 68, 0.1);
}
.state-error .btn { margin-top: 16px; }

/* ============ Screen 1 — Input ============ */
.intake { max-width: 660px; margin: 0 auto; padding: 36px 40px 30px; }
.step-kicker {
  font-size: 0.72rem; font-weight: 700; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--violet); margin: 0 0 6px;
}
.intake-title {
  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
  letter-spacing: -0.01em; margin: 0 0 6px;
}
.intake-sub { color: var(--muted); font-size: 0.95rem; margin: 0 0 22px; }
.intake-sub .crumbs { color: var(--ink); font-weight: 600; white-space: nowrap; }
.intake-sub .crumb-sep { color: #b6bdc9; padding-inline: 2px; }

.dropzone {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  text-align: center; padding: 34px 24px 30px;
  border: 2px dashed #d5d9e2; border-radius: var(--radius);
  background: #fbfbfd;
  transition: border-color 0.15s ease, background 0.15s ease;
  cursor: pointer;
}
.dropzone:hover, .dropzone:focus-within, .dropzone.is-dragover {
  border-color: var(--violet); background: rgba(108, 76, 241, 0.04);
}
.dz-icon {
  width: 46px; height: 46px; display: grid; place-items: center;
  color: var(--violet); background: rgba(108, 76, 241, 0.1);
  border-radius: 14px; margin-bottom: 6px;
}
.dz-line1 { font-weight: 700; font-size: 1.02rem; }
.dz-line2 { color: var(--muted); font-size: 0.85rem; margin-bottom: 12px; }
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  font: inherit; font-weight: 700; font-size: 0.95rem;
  border: none; border-radius: 12px; padding: 12px 22px; cursor: pointer;
  color: #fff; background: var(--violet);
  box-shadow: 0 8px 20px rgba(108, 76, 241, 0.28);
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
  text-decoration: none;
}
.btn:hover { background: var(--violet-dark); transform: translateY(-1px); }
.btn:focus-visible { outline: 3px solid var(--violet); outline-offset: 3px; }
.btn:disabled { opacity: 0.55; cursor: not-allowed; transform: none; }
.dz-alt { margin-top: 12px; font-size: 0.85rem; color: var(--muted); }
.link-quiet {
  font-weight: 700; color: var(--violet-dark); text-decoration: none;
  border-bottom: 1px solid rgba(108, 76, 241, 0.35);
  background: none; border-top: none; border-left: none; border-right: none;
  font: inherit; cursor: pointer; padding: 0;
}
.link-quiet:hover { color: var(--violet); border-bottom-color: var(--violet); }

/* Upload summary */
.statecap {
  margin: 22px 0 8px; font-size: 0.64rem; font-weight: 700;
  letter-spacing: 0.1em; text-transform: uppercase; color: #98a2b3;
}
.upload-summary {
  display: flex; align-items: center; gap: 14px;
  border: 1px solid #c7ecd9; background: var(--ok-bg);
  border-radius: 12px; padding: 13px 16px;
}
.upload-summary.is-partial { border-color: #fde3b8; background: #fff8ea; }
.us-tick {
  flex: 0 0 auto; width: 30px; height: 30px; border-radius: 50%;
  display: grid; place-items: center; color: #fff; background: var(--ok);
}
.us-body { flex: 1; min-width: 0; }
.us-main { font-weight: 700; font-size: 0.95rem; color: var(--ok-text); }
.us-sub { font-size: 0.8rem; color: var(--muted); }
.us-file {
  flex: 0 0 auto; font-size: 0.74rem; font-weight: 600; color: var(--muted);
  background: #fff; border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px;
  white-space: nowrap;
}
/* Saved-favourites provenance bar + clear control */
.saved-bar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  flex-wrap: wrap; margin-top: 10px; padding: 8px 14px;
  border: 1px solid var(--line); border-radius: 10px; background: #fff;
}
.saved-note {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 0.82rem; font-weight: 600; color: var(--ink); min-width: 0;
}
.saved-ico { flex: 0 0 auto; color: var(--violet); }
.saved-hint { font-weight: 400; color: var(--muted); }

.missing-list {
  margin: 8px 0 0; padding: 10px 14px; list-style: none;
  border: 1px solid var(--line); border-radius: 10px; background: #fff;
  font-size: 0.82rem; color: var(--muted); max-height: 160px; overflow-y: auto;
}
.missing-list li { padding: 2px 0; }
.missing-list code { font-size: 0.8rem; color: var(--ink); }

.continue-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 18px; flex-wrap: wrap; }
.continue-note { font-size: 0.82rem; color: var(--muted); }

/* Collapsed "More settings" placeholder */
.more { margin-top: 22px; border-top: 1px solid var(--line); padding-top: 6px; }
.more summary {
  display: flex; align-items: center; gap: 8px; list-style: none;
  cursor: pointer; padding: 10px 4px; font-weight: 700; font-size: 0.9rem; color: var(--ink);
  border-radius: 8px;
}
.more summary::-webkit-details-marker { display: none; }
.more summary:hover { color: var(--violet-dark); }
.more summary:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
.more-caret { transition: transform 0.15s ease; color: var(--muted); font-size: 0.7rem; }
.more[open] .more-caret { transform: rotate(180deg); }
.more-hint { margin-left: auto; font-weight: 600; font-size: 0.74rem; color: #98a2b3; }
.more-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 22px; padding: 8px 4px 14px; }
.more-field-label {
  display: block; text-transform: uppercase; letter-spacing: 0.05em;
  font-size: 0.68rem; font-weight: 700; color: var(--muted); margin: 0 0 7px;
}
.chips { display: flex; flex-wrap: wrap; gap: 6px; grid-column: 1 / -1; }
.chips-wrap { grid-column: 1 / -1; }
.chip {
  font-size: 0.78rem; font-weight: 600; padding: 6px 12px; border-radius: 999px;
  border: 1px solid var(--line); background: #fff; color: var(--muted);
}
.chip.is-on { border-color: var(--violet); color: var(--violet-dark); background: rgba(108, 76, 241, 0.07); }
.faux-input {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  font-size: 0.88rem; font-weight: 600;
  border: 1px solid var(--line); border-radius: 10px; background: #fff;
  padding: 9px 12px; color: var(--ink);
}
.faux-input .fi-caret { color: var(--muted); font-size: 0.68rem; }

/* ============ Screen 2 — Availability calendar ============ */
.cal-card { padding: 30px 28px 26px; }
.cal-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 28px; flex-wrap: wrap; }
.cal-title {
  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
  letter-spacing: -0.01em; margin: 0 0 6px;
}
.cal-sub { color: var(--muted); font-size: 0.92rem; margin: 0; max-width: 520px; }

/* The payoff number */
.hero-count { text-align: right; flex: 0 0 auto; }
.hc-num {
  font-weight: 800; font-size: 3.1rem; line-height: 1; letter-spacing: -0.02em;
  color: var(--violet-dark); white-space: nowrap;
}
.hc-num .hc-of { color: #b7bcc9; font-weight: 700; font-size: 2rem; }
.hc-num.bump { animation: countbump 0.4s ease; }
@keyframes countbump {
  0% { transform: scale(1); }
  45% { transform: scale(1.09); color: var(--violet); }
  100% { transform: scale(1); }
}
.hc-label { font-size: 0.84rem; font-weight: 600; color: var(--ink); margin-top: 2px; }
.hc-detail { font-size: 0.78rem; color: var(--muted); font-variant-numeric: tabular-nums; }

/* Toolbar: the availability legend. Colours mirror edfringe.com's own
   day-picker legend (see plan.js segClass / the --fr-* tokens below). */
.cal-toolbar {
  display: flex; align-items: center; gap: 14px 20px;
  margin: 22px 0 6px; padding-top: 18px; border-top: 1px solid var(--line);
  flex-wrap: wrap;
}
.legend { display: flex; gap: 10px 16px; flex-wrap: wrap; }
.lg { display: inline-flex; align-items: center; gap: 7px; font-size: 0.76rem; color: var(--muted); }
.lg i { width: 14px; height: 11px; border-radius: 3px; display: block; }
.lg-avail i   { background: var(--fr-avail); }
.lg-2for1 i   { background: var(--fr-2for1); }
.lg-preview i { background: var(--fr-preview); }
.lg-free i    { background: var(--fr-free); }
.lg-event i   { background: var(--fr-event); }
.lg-noalloc i { background: var(--fr-noalloc); }
.lg-sold i    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }
/* A miniature two-segment cell, matching the split used in the calendar. */
.lg-multi i.multi { display: inline-flex; gap: 1.5px; background: none; width: 16px; }
.lg-multi i.multi b { flex: 1; border-radius: 2px; }
.lg-multi i.multi b:first-child { background: var(--fr-avail); }
.lg-multi i.multi b:last-child { background: var(--fr-2for1); }

/* --- The calendar canvas --- */
/* .cal-wrap is the scroll container: day-header stays sticky at its top while
   the lane list scrolls beneath it. The toolbar/hero-count above are outside
   this container entirely, so they never scroll away either. */
.cal-wrap {
  position: relative; margin-top: 14px;
  max-height: 62vh; overflow-y: auto; overflow-x: hidden;
  border-radius: 10px;
}
.cal-inner { position: relative; padding-top: 40px; /* room for the handle flags */ }

.cal-row { display: grid; grid-template-columns: 190px 1fr 52px; gap: 0 14px; align-items: center; }

.cal-head {
  border-bottom: 1px solid var(--line); padding-bottom: 6px;
  position: sticky; top: 0; z-index: 4; background: var(--paper);
}
.cal-head-left { font-size: 0.72rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--muted); }
.cal-head-right { font-size: 0.62rem; font-weight: 600; color: #98a2b3; text-align: center; line-height: 1.15; }
.days { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; }
.day-col { text-align: center; line-height: 1.15; }
.day-dow { display: block; font-size: 0.56rem; font-weight: 600; color: #b0b7c3; }
.day-num { display: block; font-size: 0.7rem; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
.day-col.wknd .day-num { color: var(--ink); font-weight: 700; }
.day-col.post .day-num, .day-col.post .day-dow { color: #cfd4de; }

.lanes { position: relative; z-index: 1; }
/* One tight single-line row per show — this screen is an overview of the shows
   you want, so each row is deliberately compact (title only, no meta line). */
.lane { min-height: 22px; padding: 1px 0; border-bottom: 1px solid #f1f2f6; }
.lane:last-child { border-bottom: none; }
.lane-label { min-width: 0; }
.lane-title {
  font-family: var(--display); font-weight: 600; font-size: 0.8rem; line-height: 1.2;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.lane-track { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; align-items: center; height: 100%; }

/* A day cell holds one coloured segment per performance; two performances on a
   day render as two side-by-side segments — the split IS the "two shows that
   day" cue. Single-performance days read as one solid bar. */
.cell { height: 10px; border-radius: 3px; display: flex; gap: 0; overflow: hidden; }
.cell-multi { gap: 1.5px; }
.seg { flex: 1 1 0; min-width: 0; border-radius: 3px; }
.seg-avail   { background: var(--fr-avail); }
.seg-2for1   { background: var(--fr-2for1); }
.seg-preview { background: var(--fr-preview); }
.seg-free    { background: var(--fr-free); }
.seg-event   { background: var(--fr-event); }
.seg-noalloc { background: var(--fr-noalloc); }
.seg-sold    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }

.lane-status { font-size: 0.78rem; line-height: 1.2; text-align: center; }
.lane-status .st-ok { font-weight: 700; color: var(--ok-text); font-variant-numeric: tabular-nums; }
.lane-status .st-no { color: #c2c8d2; font-weight: 700; }
/* A show with nothing catchable in the window recedes as a whole. */
.lane--out .lane-title { opacity: 0.42; }
.lane--out .lane-track { opacity: 0.35; }

/* --- Window overlay: dim panels, highlight band, drag handles --- */
.win { position: absolute; top: 0; bottom: 0; z-index: 2; pointer-events: none; }
.festend { position: absolute; top: 40px; bottom: 0; background: rgba(234, 236, 240, 0.35); border-left: 1px dashed #d5d9e2; pointer-events: none; z-index: 1; }
.win-dim { position: absolute; top: 40px; bottom: 0; background: rgba(247, 248, 250, 0.72); }
.win-band {
  position: absolute; top: 40px; bottom: 0;
  background: rgba(108, 76, 241, 0.05);
  border-left: 2px solid var(--violet); border-right: 2px solid var(--violet);
  cursor: grab; pointer-events: auto; touch-action: none;
}
.win-band:active { cursor: grabbing; }
.win-handle {
  position: absolute; top: 0; bottom: 0; width: 26px;
  transform: translateX(-50%);
  pointer-events: auto; cursor: ew-resize; touch-action: none;
}
/* Flags anchor OUTWARD from their line (start points left, end points right),
   so they never collide even when the window is dragged narrow. */
.win-flag {
  position: absolute; top: 2px;
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 0.72rem; font-weight: 700; color: var(--violet-dark);
  background: #fff; border: 1.5px solid var(--violet); border-radius: 999px;
  padding: 4px 11px; white-space: nowrap;
  box-shadow: 0 3px 10px rgba(16, 24, 40, 0.12);
  font-variant-numeric: tabular-nums;
}
.win-handle--start .win-flag { right: 50%; margin-right: -2px; }
.win-handle--end .win-flag { left: 50%; margin-left: -2px; }
.win-flag .grip { display: inline-flex; gap: 2px; }
.win-flag .grip i { width: 2.5px; height: 9px; border-radius: 2px; background: rgba(108, 76, 241, 0.5); display: block; }
.win-handle:hover .win-flag, .win-handle:focus-visible .win-flag {
  background: var(--violet); color: #fff; border-color: var(--violet);
}
.win-handle:hover .win-flag .grip i, .win-handle:focus-visible .win-flag .grip i { background: rgba(255, 255, 255, 0.75); }
.win-handle:focus-visible { outline: none; }
.win-handle:focus-visible .win-flag { box-shadow: 0 0 0 3px rgba(108, 76, 241, 0.35); }

.cal-foot {
  display: flex; justify-content: space-between; gap: 20px;
  margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line);
  font-size: 0.78rem; color: var(--muted); flex-wrap: wrap;
}

/* ============ Footer ============ */
.site-footer { background: var(--ink); color: #d9d9d9; padding: 28px 0; margin-top: 56px; }
.footer-inner { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.footer-copy { color: #8c8c8c; font-size: 0.85rem; }

@media (prefers-reduced-motion: reduce) {
  .hc-num.bump { animation: none; }
  html { scroll-behavior: auto; }
}

