+.seg-2for1   { background: var(--fr-2for1); }
+.seg-preview { background: var(--fr-preview); }
+.seg-free    { background: var(--fr-free); }
+.seg-event   { background: var(--fr-event); }
+.seg-noalloc { background: var(--fr-noalloc); }
+.seg-sold    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }
+
+.lane-status { font-size: 0.78rem; line-height: 1.2; text-align: center; }
+.lane-status .st-ok { font-weight: 700; color: var(--ok-text); font-variant-numeric: tabular-nums; }
+.lane-status .st-no { color: #c2c8d2; font-weight: 700; }
+/* A show with nothing catchable in the window recedes as a whole. */
+.lane--out .lane-title { opacity: 0.42; }
+.lane--out .lane-track { opacity: 0.35; }
+
+/* --- Window overlay: dim panels, highlight band, drag handles --- */
+.win { position: absolute; top: 0; bottom: 0; z-index: 2; pointer-events: none; }
+.festend { position: absolute; top: 40px; bottom: 0; background: rgba(234, 236, 240, 0.35); border-left: 1px dashed #d5d9e2; pointer-events: none; z-index: 1; }
+.win-dim { position: absolute; top: 40px; bottom: 0; background: rgba(247, 248, 250, 0.72); }
+.win-band {
+  position: absolute; top: 40px; bottom: 0;
+  background: rgba(108, 76, 241, 0.05);
+  border-left: 2px solid var(--violet); border-right: 2px solid var(--violet);
+  cursor: grab; pointer-events: auto; touch-action: none;
+}
+.win-band:active { cursor: grabbing; }
+.win-handle {
+  position: absolute; top: 0; bottom: 0; width: 26px;
+  transform: translateX(-50%);
+  pointer-events: auto; cursor: ew-resize; touch-action: none;
+}
+/* Flags anchor OUTWARD from their line (start points left, end points right),
+   so they never collide even when the window is dragged narrow. */
+.win-flag {
+  position: absolute; top: 2px;
+  display: inline-flex; align-items: center; gap: 6px;
+  font-size: 0.72rem; font-weight: 700; color: var(--violet-dark);
+  background: #fff; border: 1.5px solid var(--violet); border-radius: 999px;
+  padding: 4px 11px; white-space: nowrap;
+  box-shadow: 0 3px 10px rgba(16, 24, 40, 0.12);
+  font-variant-numeric: tabular-nums;
+}
+.win-handle--start .win-flag { right: 50%; margin-right: -2px; }
+.win-handle--end .win-flag { left: 50%; margin-left: -2px; }
+.win-flag .grip { display: inline-flex; gap: 2px; }
+.win-flag .grip i { width: 2.5px; height: 9px; border-radius: 2px; background: rgba(108, 76, 241, 0.5); display: block; }
+.win-handle:hover .win-flag, .win-handle:focus-visible .win-flag {
+  background: var(--violet); color: #fff; border-color: var(--violet);
+}
+.win-handle:hover .win-flag .grip i, .win-handle:focus-visible .win-flag .grip i { background: rgba(255, 255, 255, 0.75); }
+.win-handle:focus-visible { outline: none; }
+.win-handle:focus-visible .win-flag { box-shadow: 0 0 0 3px rgba(108, 76, 241, 0.35); }
+
+.cal-foot {
+  display: flex; justify-content: space-between; gap: 20px;
+  margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line);
+  font-size: 0.78rem; color: var(--muted); flex-wrap: wrap;
+}
+
+/* ============ Footer ============ */
+.site-footer { background: var(--ink); color: #d9d9d9; padding: 28px 0; margin-top: 56px; }
+.footer-inner { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
+.footer-copy { color: #8c8c8c; font-size: 0.85rem; }
+
+@media (prefers-reduced-motion: reduce) {
+  .hc-num.bump { animation: none; }
+  html { scroll-behavior: auto; }
+}

