+.cal-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 28px; flex-wrap: wrap; }
+.cal-title {
+  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
+  letter-spacing: -0.01em; margin: 0 0 6px;
+}
+.cal-sub { color: var(--muted); font-size: 0.92rem; margin: 0; max-width: 520px; }
+
+/* The payoff number */
+.hero-count { text-align: right; flex: 0 0 auto; }
+.hc-num {
+  font-weight: 800; font-size: 3.1rem; line-height: 1; letter-spacing: -0.02em;
+  color: var(--violet-dark); white-space: nowrap;
+}
+.hc-num .hc-of { color: #b7bcc9; font-weight: 700; font-size: 2rem; }
+.hc-num.bump { animation: countbump 0.4s ease; }
+@keyframes countbump {
+  0% { transform: scale(1); }
+  45% { transform: scale(1.09); color: var(--violet); }
+  100% { transform: scale(1); }
+}
+.hc-label { font-size: 0.84rem; font-weight: 600; color: var(--ink); margin-top: 2px; }
+.hc-detail { font-size: 0.78rem; color: var(--muted); font-variant-numeric: tabular-nums; }
+
+/* Toolbar: the availability legend. Colours mirror edfringe.com's own
+   day-picker legend (see plan.js segClass / the --fr-* tokens below). */
+.cal-toolbar {
+  display: flex; align-items: center; gap: 14px 20px;
+  margin: 22px 0 6px; padding-top: 18px; border-top: 1px solid var(--line);
+  flex-wrap: wrap;
+}
+.legend { display: flex; gap: 10px 16px; flex-wrap: wrap; }
+.lg { display: inline-flex; align-items: center; gap: 7px; font-size: 0.76rem; color: var(--muted); }
+.lg i { width: 14px; height: 11px; border-radius: 3px; display: block; }
+.lg-avail i   { background: var(--fr-avail); }
+.lg-2for1 i   { background: var(--fr-2for1); }
+.lg-preview i { background: var(--fr-preview); }
+.lg-free i    { background: var(--fr-free); }
+.lg-event i   { background: var(--fr-event); }
+.lg-noalloc i { background: var(--fr-noalloc); }
+.lg-sold i    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }
+/* A miniature two-segment cell, matching the split used in the calendar. */
+.lg-multi i.multi { display: inline-flex; gap: 1.5px; background: none; width: 16px; }
+.lg-multi i.multi b { flex: 1; border-radius: 2px; }
+.lg-multi i.multi b:first-child { background: var(--fr-avail); }
+.lg-multi i.multi b:last-child { background: var(--fr-2for1); }
+
+/* --- The calendar canvas --- */
+/* .cal-wrap is the scroll container: day-header stays sticky at its top while
+   the lane list scrolls beneath it. The toolbar/hero-count above are outside
+   this container entirely, so they never scroll away either. */
+.cal-wrap {
+  position: relative; margin-top: 14px;
+  max-height: 62vh; overflow-y: auto; overflow-x: hidden;
+  border-radius: 10px;
+}
+.cal-inner { position: relative; padding-top: 40px; /* room for the handle flags */ }
+
+.cal-row { display: grid; grid-template-columns: 190px 1fr 52px; gap: 0 14px; align-items: center; }
+
+.cal-head {
+  border-bottom: 1px solid var(--line); padding-bottom: 6px;
+  position: sticky; top: 0; z-index: 4; background: var(--paper);
+}
+.cal-head-left { font-size: 0.72rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--muted); }
+.cal-head-right { font-size: 0.62rem; font-weight: 600; color: #98a2b3; text-align: center; line-height: 1.15; }
+.days { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; }
+.day-col { text-align: center; line-height: 1.15; }
+.day-dow { display: block; font-size: 0.56rem; font-weight: 600; color: #b0b7c3; }
+.day-num { display: block; font-size: 0.7rem; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
+.day-col.wknd .day-num { color: var(--ink); font-weight: 700; }
+.day-col.post .day-num, .day-col.post .day-dow { color: #cfd4de; }
+
+.lanes { position: relative; z-index: 1; }
+/* One tight single-line row per show — this screen is an overview of the shows
+   you want, so each row is deliberately compact (title only, no meta line). */
+.lane { min-height: 22px; padding: 1px 0; border-bottom: 1px solid #f1f2f6; }
+.lane:last-child { border-bottom: none; }
+.lane-label { min-width: 0; }
+.lane-title {
+  font-family: var(--display); font-weight: 600; font-size: 0.8rem; line-height: 1.2;
+  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
+}
+.lane-track { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; align-items: center; height: 100%; }
+
+/* A day cell holds one coloured segment per performance; two performances on a
+   day render as two side-by-side segments — the split IS the "two shows that
+   day" cue. Single-performance days read as one solid bar. */
+.cell { height: 10px; border-radius: 3px; display: flex; gap: 0; overflow: hidden; }
+.cell-multi { gap: 1.5px; }
+.seg { flex: 1 1 0; min-width: 0; border-radius: 3px; }
+.seg-avail   { background: var(--fr-avail); }
+.seg-2for1   { background: var(--fr-2for1); }
+.seg-preview { background: var(--fr-preview); }
+.seg-free    { background: var(--fr-free); }
+.seg-event   { background: var(--fr-event); }
+.seg-noalloc { background: var(--fr-noalloc); }
+.seg-sold    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }
+
+.lane-status { font-size: 0.78rem; line-height: 1.2; text-align: center; }
+.lane-status .st-ok { font-weight: 700; color: var(--ok-text); font-variant-numeric: tabular-nums; }
+.lane-status .st-no { color: #c2c8d2; font-weight: 700; }
+/* A show with nothing catchable in the window recedes as a whole. */
+.lane--out .lane-title { opacity: 0.42; }
+.lane--out .lane-track { opacity: 0.35; }
+
+/* --- Window overlay: dim panels, highlight band, drag handles --- */
+.win { position: absolute; top: 0; bottom: 0; z-index: 2; pointer-events: none; }
+.festend { position: absolute; top: 40px; bottom: 0; background: rgba(234, 236, 240, 0.35); border-left: 1px dashed #d5d9e2; pointer-events: none; z-index: 1; }
+.win-dim { position: absolute; top: 40px; bottom: 0; background: rgba(247, 248, 250, 0.72); }
+.win-band {
+  position: absolute; top: 40px; bottom: 0;
+  background: rgba(108, 76, 241, 0.05);
+  border-left: 2px solid var(--violet); border-right: 2px solid var(--violet);
+  cursor: grab; pointer-events: auto; touch-action: none;
+}
+.win-band:active { cursor: grabbing; }
+.win-handle {
+  position: absolute; top: 0; bottom: 0; width: 26px;
+  transform: translateX(-50%);
+  pointer-events: auto; cursor: ew-resize; touch-action: none;
+}
+/* Flags anchor OUTWARD from their line (start points left, end points right),
+   so they never collide even when the window is dragged narrow. */
+.win-flag {
+  position: absolute; top: 2px;
+  display: inline-flex; align-items: center; gap: 6px;
+  font-size: 0.72rem; font-weight: 700; color: var(--violet-dark);
+  background: #fff; border: 1.5px solid var(--violet); border-radius: 999px;
+  padding: 4px 11px; white-space: nowrap;
+  box-shadow: 0 3px 10px rgba(16, 24, 40, 0.12);
+  font-variant-numeric: tabular-nums;
+}
+.win-handle--start .win-flag { right: 50%; margin-right: -2px; }
+.win-handle--end .win-flag { left: 50%; margin-left: -2px; }
+.win-flag .grip { display: inline-flex; gap: 2px; }
+.win-flag .grip i { width: 2.5px; height: 9px; border-radius: 2px; background: rgba(108, 76, 241, 0.5); display: block; }
+.win-handle:hover .win-flag, .win-handle:focus-visible .win-flag {
+  background: var(--violet); color: #fff; border-color: var(--violet);
+}
+.win-handle:hover .win-flag .grip i, .win-handle:focus-visible .win-flag .grip i { background: rgba(255, 255, 255, 0.75); }
+.win-handle:focus-visible { outline: none; }
+.win-handle:focus-visible .win-flag { box-shadow: 0 0 0 3px rgba(108, 76, 241, 0.35); }
+
+.cal-foot {
+  display: flex; justify-content: space-between; gap: 20px;
+  margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line);
+  font-size: 0.78rem; color: var(--muted); flex-wrap: wrap;
+}
+
+/* ============ Footer ============ */
+.site-footer { background: var(--ink); color: #d9d9d9; padding: 28px 0; margin-top: 56px; }
+.footer-inner { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
+.footer-copy { color: #8c8c8c; font-size: 0.85rem; }
+
+@media (prefers-reduced-motion: reduce) {
+  .hc-num.bump { animation: none; }
+  html { scroll-behavior: auto; }
+}

