@@ -0,0 +1,439 @@
+/* Fringe Planner — stylesheet
+ * Extracted/adapted from plan/design/mock.html. Brand tokens match the home
+ * site's css/styles.css (violet #6c4cf1, ink/muted/hairline, 16px radius,
+ * soft shadow, Plus Jakarta Sans display + Inter body, 1120px container).
+ * This stylesheet is self-contained — the planner does not load styles.css.
+ */
+
+:root {
+  --violet: #6c4cf1;
+  --violet-dark: #5a3fd6;
+  --ink: #101828;
+  --paper: #ffffff;
+  --bg: #f7f8fa;
+  --muted: #667085;
+  --line: #eaecf0;
+  --ok: #059669;
+  --ok-text: #047857;
+  --ok-bg: #e6f7ee;
+  --warn: #ef4444;
+  /* Performance-date availability palette — taken from edfringe.com's own
+     ticket day-picker legend so the calendar reads the same as the official
+     site. Violet stays reserved for the date-window instrument + chrome. */
+  --fr-avail: #2ac9de;    /* tickets available */
+  --fr-2for1: #ffce00;    /* 2-for-1 */
+  --fr-preview: #3438ff;  /* preview show */
+  --fr-free: #00bf57;     /* free (ticketed / non-ticketed) */
+  --fr-event: #8c4fd9;    /* event-specific */
+  --fr-noalloc: #ef3934;  /* no allocation — contact venue */
+  --fr-sold-bg: #e6e9ef;  /* sold out — greyed, as the official picker disables it */
+  --fr-sold-line: #c6cdda;
+  --fr-ink: #00243d;      /* edfringe.com ink */
+  --shadow-soft: 0 12px 30px rgba(16, 24, 40, 0.08);
+  --maxw: 1120px;
+  --radius: 16px;
+  --sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
+  --display: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;
+}
+* { box-sizing: border-box; }
+html { scroll-behavior: smooth; }
+body {
+  margin: 0;
+  font-family: var(--sans);
+  color: var(--ink);
+  background: var(--bg);
+  line-height: 1.5;
+}
+[hidden] { display: none !important; }
+.container { width: 100%; max-width: var(--maxw); margin: 0 auto; padding-inline: 24px; }
+a { color: inherit; }
+.sr-only {
+  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
+}
+
+/* ============ Header ============ */
+.site-header {
+  border-bottom: 1px solid var(--line);
+  position: sticky; top: 0; z-index: 50;
+  background: rgba(255, 255, 255, 0.95);
+  backdrop-filter: blur(6px);
+}
+.header-inner { display: flex; align-items: center; height: 64px; gap: 24px; }
+.logo {
+  font-family: var(--display); font-weight: 700; font-size: 1.4rem;
+  letter-spacing: -0.01em; text-decoration: none; white-space: nowrap;
+}
+.logo-now { color: var(--violet); }
+.main-nav { display: flex; gap: 28px; margin-inline: auto; }
+.nav-link {
+  text-decoration: none; font-size: 0.98rem; padding-bottom: 2px;
+  border-bottom: 2px solid transparent; color: var(--ink);
+}
+.nav-link:hover { color: var(--violet); }
+.nav-link.is-active { color: var(--violet); border-bottom-color: var(--violet); }
+.header-hint { font-size: 0.8rem; color: var(--muted); white-space: nowrap; }
+
+/* ============ Page head ============ */
+.page-head { padding: 44px 0 8px; }
+.page-kicker {
+  display: inline-block; font-size: 0.72rem; font-weight: 700;
+  letter-spacing: 0.08em; text-transform: uppercase; color: var(--violet);
+  background: rgba(108, 76, 241, 0.09); border-radius: 999px; padding: 5px 12px;
+  margin: 0 0 12px;
+}
+.page-title {
+  font-family: var(--display); font-weight: 700; letter-spacing: -0.01em;
+  font-size: 2.3rem; line-height: 1.12; margin: 0 0 8px;
+}
+.page-sub { color: var(--muted); font-size: 1.02rem; max-width: 640px; margin: 0; }
+
+.panel {
+  background: var(--paper);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  box-shadow: var(--shadow-soft);
+}
+
+/* ============ Loading / error states ============ */
+.state-panel {
+  max-width: 660px; margin: 40px auto; padding: 40px 32px;
+  text-align: center; border-radius: var(--radius);
+  background: var(--paper); border: 1px solid var(--line); box-shadow: var(--shadow-soft);
+}
+.state-spinner {
+  width: 34px; height: 34px; margin: 0 auto 16px; border-radius: 50%;
+  border: 3px solid var(--line); border-top-color: var(--violet);
+  animation: spin 0.8s linear infinite;
+}
+@keyframes spin { to { transform: rotate(360deg); } }
+.state-title { font-family: var(--display); font-weight: 700; font-size: 1.15rem; margin: 0 0 6px; }
+.state-sub { color: var(--muted); font-size: 0.92rem; margin: 0; }
+.state-error .state-icon {
+  width: 44px; height: 44px; margin: 0 auto 14px; border-radius: 50%;
+  display: grid; place-items: center; color: var(--warn); background: rgba(239, 68, 68, 0.1);
+}
+.state-error .btn { margin-top: 16px; }
+
+/* ============ Intake (no favourites yet) ============ */
+.intake { max-width: 660px; margin: 0 auto; padding: 36px 40px 30px; }
+.intake-title {
+  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
+  letter-spacing: -0.01em; margin: 0 0 6px;
+}
+.intake-sub { color: var(--muted); font-size: 0.95rem; margin: 0 0 22px; }
+.intake-sub .crumbs { color: var(--ink); font-weight: 600; white-space: nowrap; }
+.intake-sub .crumb-sep { color: #b6bdc9; padding-inline: 2px; }
+
+.dropzone {
+  display: flex; flex-direction: column; align-items: center; gap: 6px;
+  text-align: center; padding: 34px 24px 30px;
+  border: 2px dashed #d5d9e2; border-radius: var(--radius);
+  background: #fbfbfd;
+  transition: border-color 0.15s ease, background 0.15s ease;
+  cursor: pointer;
+}
+.dropzone:hover, .dropzone:focus-within, .dropzone.is-dragover {
+  border-color: var(--violet); background: rgba(108, 76, 241, 0.04);
+}
+.dz-icon {
+  width: 46px; height: 46px; display: grid; place-items: center;
+  color: var(--violet); background: rgba(108, 76, 241, 0.1);
+  border-radius: 14px; margin-bottom: 6px;
+}
+.dz-line1 { font-weight: 700; font-size: 1.02rem; }
+.dz-line2 { color: var(--muted); font-size: 0.85rem; margin-bottom: 12px; }
+.btn {
+  display: inline-flex; align-items: center; gap: 8px;
+  font: inherit; font-weight: 700; font-size: 0.95rem;
+  border: none; border-radius: 12px; padding: 12px 22px; cursor: pointer;
+  color: #fff; background: var(--violet);
+  box-shadow: 0 8px 20px rgba(108, 76, 241, 0.28);
+  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
+  text-decoration: none;
+}
+.btn:hover { background: var(--violet-dark); transform: translateY(-1px); }
+.btn:focus-visible { outline: 3px solid var(--violet); outline-offset: 3px; }
+.btn:disabled { opacity: 0.55; cursor: not-allowed; transform: none; }
+.dz-alt { margin-top: 12px; font-size: 0.85rem; color: var(--muted); }
+.dz-privacy { margin: 6px 0 0; font-size: 0.78rem; color: #98a2b3; }
+.link-quiet {
+  font-weight: 700; color: var(--violet-dark); text-decoration: none;
+  border-bottom: 1px solid rgba(108, 76, 241, 0.35);
+  background: none; border-top: none; border-left: none; border-right: none;
+  font: inherit; cursor: pointer; padding: 0;
+}
+.link-quiet:hover { color: var(--violet); border-bottom-color: var(--violet); }
+
+/* Upload summary (failure feedback only — the calendar takes over on success) */
+.upload-summary {
+  display: flex; align-items: center; gap: 14px;
+  margin-top: 22px;
+  border: 1px solid #c7ecd9; background: var(--ok-bg);
+  border-radius: 12px; padding: 13px 16px;
+}
+.upload-summary.is-partial { border-color: #fde3b8; background: #fff8ea; }
+.us-tick {
+  flex: 0 0 auto; width: 30px; height: 30px; border-radius: 50%;
+  display: grid; place-items: center; color: #fff; background: var(--ok);
+}
+.us-body { flex: 1; min-width: 0; }
+.us-main { font-weight: 700; font-size: 0.95rem; color: var(--ok-text); }
+.us-sub { font-size: 0.8rem; color: var(--muted); }
+.us-file {
+  flex: 0 0 auto; font-size: 0.74rem; font-weight: 600; color: var(--muted);
+  background: #fff; border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px;
+  white-space: nowrap;
+}
+.missing-list {
+  margin: 8px 0 0; padding: 10px 14px; list-style: none;
+  border: 1px solid var(--line); border-radius: 10px; background: #fff;
+  font-size: 0.82rem; color: var(--muted); max-height: 160px; overflow-y: auto;
+}
+.missing-list li { padding: 2px 0; }
+.missing-list code { font-size: 0.8rem; color: var(--ink); }
+
+/* Collapsed "More settings" placeholder */
+.more { margin-top: 22px; border-top: 1px solid var(--line); padding-top: 6px; }
+.more summary {
+  display: flex; align-items: center; gap: 8px; list-style: none;
+  cursor: pointer; padding: 10px 4px; font-weight: 700; font-size: 0.9rem; color: var(--ink);
+  border-radius: 8px;
+}
+.more summary::-webkit-details-marker { display: none; }
+.more summary:hover { color: var(--violet-dark); }
+.more summary:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
+.more-caret { transition: transform 0.15s ease; color: var(--muted); font-size: 0.7rem; }
+.more[open] .more-caret { transform: rotate(180deg); }
+.more-hint { margin-left: auto; font-weight: 600; font-size: 0.74rem; color: #98a2b3; }
+.more-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 22px; padding: 8px 4px 14px; }
+.more-field-label {
+  display: block; text-transform: uppercase; letter-spacing: 0.05em;
+  font-size: 0.68rem; font-weight: 700; color: var(--muted); margin: 0 0 7px;
+}
+.chips { display: flex; flex-wrap: wrap; gap: 6px; grid-column: 1 / -1; }
+.chips-wrap { grid-column: 1 / -1; }
+.chip {
+  font-size: 0.78rem; font-weight: 600; padding: 6px 12px; border-radius: 999px;
+  border: 1px solid var(--line); background: #fff; color: var(--muted);
+}
+.chip.is-on { border-color: var(--violet); color: var(--violet-dark); background: rgba(108, 76, 241, 0.07); }
+.faux-input {
+  display: flex; align-items: center; justify-content: space-between; gap: 8px;
+  font-size: 0.88rem; font-weight: 600;
+  border: 1px solid var(--line); border-radius: 10px; background: #fff;
+  padding: 9px 12px; color: var(--ink);
+}
+.faux-input .fi-caret { color: var(--muted); font-size: 0.68rem; }
+
+/* ============ Availability calendar ============ */
+.cal-card { padding: 30px 28px 26px; }
+.cal-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 28px; flex-wrap: wrap; }
+.cal-top-left { min-width: 0; max-width: 640px; }
+.cal-title {
+  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
+  letter-spacing: -0.01em; margin: 0 0 6px;
+}
+
+/* The favourites provenance line: what's loaded, plus quiet replace/clear
+   actions — deliberately low-key, no button chrome, no accent colour. */
+.fav-line {
+  display: flex; align-items: baseline; gap: 4px 8px; flex-wrap: wrap;
+  margin: 0; font-size: 0.85rem; color: var(--muted);
+}
+.fav-action {
+  font: inherit; font-size: 0.82rem; color: var(--muted);
+  background: none; border: none; padding: 0; cursor: pointer;
+  text-decoration: underline; text-underline-offset: 2px;
+  text-decoration-color: #c6cdda;
+}
+.fav-action:hover { color: var(--ink); text-decoration-color: currentColor; }
+.fav-sep { color: #c6cdda; }
+
+/* The payoff number */
+.hero-count { text-align: right; flex: 0 0 auto; }
+.hc-num {
+  font-weight: 800; font-size: 3.1rem; line-height: 1; letter-spacing: -0.02em;
+  color: var(--violet-dark); white-space: nowrap;
+}
+.hc-num .hc-of { color: #b7bcc9; font-weight: 700; font-size: 2rem; }
+.hc-num.bump { animation: countbump 0.4s ease; }
+@keyframes countbump {
+  0% { transform: scale(1); }
+  45% { transform: scale(1.09); color: var(--violet); }
+  100% { transform: scale(1); }
+}
+.hc-label { font-size: 0.84rem; font-weight: 600; color: var(--ink); margin-top: 2px; }
+.hc-detail { font-size: 0.78rem; color: var(--muted); font-variant-numeric: tabular-nums; }
+
+/* Toolbar: the availability legend. Colours mirror edfringe.com's own
+   day-picker legend (see plan.js segClass / the --fr-* tokens below). */
+.cal-toolbar {
+  display: flex; align-items: center; gap: 14px 20px;
+  margin: 22px 0 6px; padding-top: 18px; border-top: 1px solid var(--line);
+  flex-wrap: wrap;
+}
+.legend { display: flex; gap: 10px 16px; flex-wrap: wrap; }
+.lg { display: inline-flex; align-items: center; gap: 7px; font-size: 0.76rem; color: var(--muted); }
+.lg i { width: 14px; height: 11px; border-radius: 3px; display: block; }
+.lg-avail i   { background: var(--fr-avail); }
+.lg-2for1 i   { background: var(--fr-2for1); }
+.lg-preview i { background: var(--fr-preview); }
+.lg-free i    { background: var(--fr-free); }
+.lg-event i   { background: var(--fr-event); }
+.lg-noalloc i { background: var(--fr-noalloc); }
+.lg-sold i    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }
+/* A miniature two-segment cell, matching the split used in the calendar. */
+.lg-multi i.multi { display: inline-flex; gap: 1.5px; background: none; width: 16px; }
+.lg-multi i.multi b { flex: 1; border-radius: 2px; }
+.lg-multi i.multi b:first-child { background: var(--fr-avail); }
+.lg-multi i.multi b:last-child { background: var(--fr-2for1); }
+
+/* --- The calendar canvas --- */
+/* .cal-wrap is the scroll container: the sticky block (window-control rail +
+   day header) stays at its top while the lane list scrolls beneath it. The
+   toolbar/hero-count above are outside this container entirely, so they never
+   scroll away either. */
+.cal-wrap {
+  position: relative; margin-top: 14px;
+  max-height: 62vh; overflow-y: auto; overflow-x: hidden;
+  border-radius: 10px;
+}
+.cal-inner { position: relative; }
+
+.cal-sticky { position: sticky; top: 0; z-index: 4; background: var(--paper); }
+
+.cal-row { display: grid; grid-template-columns: 190px 1fr 52px; gap: 0 14px; align-items: center; }
+
+.cal-head { border-bottom: 1px solid var(--line); padding-bottom: 6px; }
+.cal-head-right { font-size: 0.62rem; font-weight: 600; color: #98a2b3; text-align: center; line-height: 1.15; }
+.days { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; }
+.day-col { text-align: center; line-height: 1.15; }
+.day-dow { display: block; font-size: 0.56rem; font-weight: 600; color: #b0b7c3; }
+.day-num { display: block; font-size: 0.7rem; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
+.day-col.wknd .day-num { color: var(--ink); font-weight: 700; }
+.day-col.post .day-num, .day-col.post .day-dow { color: #cfd4de; }
+
+.lanes { position: relative; z-index: 1; }
+/* One tight single-line row per show — this screen is an overview of the shows
+   you want, so each row is deliberately compact (title only, no meta line). */
+.lane { min-height: 22px; padding: 1px 0; border-bottom: 1px solid #f1f2f6; }
+.lane:last-child { border-bottom: none; }
+.lane-label { min-width: 0; }
+.lane-title {
+  font-family: var(--display); font-weight: 600; font-size: 0.8rem; line-height: 1.2;
+  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
+}
+.lane-track { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; align-items: center; height: 100%; }
+
+/* A day cell holds one coloured segment per performance; two performances on a
+   day render as two side-by-side segments — the split IS the "two shows that
+   day" cue. Single-performance days read as one solid bar. */
+.cell { height: 10px; border-radius: 3px; display: flex; gap: 0; overflow: hidden; }
+.cell-multi { gap: 1.5px; }
+.seg { flex: 1 1 0; min-width: 0; border-radius: 3px; }
+.seg-avail   { background: var(--fr-avail); }
+.seg-2for1   { background: var(--fr-2for1); }
+.seg-preview { background: var(--fr-preview); }
+.seg-free    { background: var(--fr-free); }
+.seg-event   { background: var(--fr-event); }
+.seg-noalloc { background: var(--fr-noalloc); }
+.seg-sold    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }
+
+.lane-status { font-size: 0.78rem; line-height: 1.2; text-align: center; }
+.lane-status .st-ok { font-weight: 700; color: var(--ok-text); font-variant-numeric: tabular-nums; }
+.lane-status .st-no { color: #c2c8d2; font-weight: 700; }
+/* A show with nothing catchable in the window recedes as a whole. */
+.lane--out .lane-title { opacity: 0.42; }
+.lane--out .lane-track { opacity: 0.35; }
+
+/* --- Window controls: the rail (sticky, above the day header) --- */
+/* All dragging lives here: the two handle tabs resize the window; the space
+   between them slides the whole window. */
+.win-rail { position: relative; height: 38px; }
+.rail-band {
+  position: absolute; top: 6px; bottom: 0;
+  background: rgba(108, 76, 241, 0.07);
+  border-radius: 8px 8px 0 0;
+  cursor: grab; touch-action: none;
+}
+.rail-band:active { cursor: grabbing; }
+/* A centred grip bar so the between-space reads as draggable. */
+.rail-band::before {
+  content: ""; position: absolute; left: 50%; top: 50%;
+  transform: translate(-50%, -50%);
+  width: 26px; height: 4px; border-radius: 2px;
+  background: rgba(108, 76, 241, 0.35);
+}
+.rail-band:hover::before { background: rgba(108, 76, 241, 0.6); }
+
+.win-handle {
+  position: absolute; top: 0; bottom: 0; width: 26px;
+  transform: translateX(-50%);
+  cursor: ew-resize; touch-action: none; z-index: 1;
+}
+/* The tab's stem: a short violet line down to the day header, continuing
+   visually into the band edge below the header. */
+.win-handle::before {
+  content: ""; position: absolute; left: 50%; top: 6px; bottom: 0;
+  width: 2px; margin-left: -1px; background: var(--violet);
+}
+/* Handle tabs anchor OUTWARD from their line (start points left, end points
+   right), so they never collide even when the window is dragged narrow. */
+.win-flag {
+  position: absolute; top: 2px;
+  display: inline-flex; align-items: center; gap: 7px;
+  font-size: 0.72rem; font-weight: 700; color: var(--violet-dark);
+  background: #fff; border: 1.5px solid var(--violet); border-radius: 8px;
+  padding: 5px 10px; white-space: nowrap;
+  box-shadow: 0 3px 10px rgba(16, 24, 40, 0.15);
+  font-variant-numeric: tabular-nums;
+  cursor: ew-resize;
+}
+.win-handle--start .win-flag { right: 50%; margin-right: -2px; }
+.win-handle--end .win-flag { left: 50%; margin-left: -2px; }
+.win-flag .grip { display: inline-flex; gap: 2.5px; }
+.win-flag .grip i { width: 3px; height: 12px; border-radius: 2px; background: rgba(108, 76, 241, 0.5); display: block; }
+.win-handle:hover .win-flag, .win-handle:focus-visible .win-flag {
+  background: var(--violet); color: #fff; border-color: var(--violet);
+}
+.win-handle:hover .win-flag .grip i, .win-handle:focus-visible .win-flag .grip i { background: rgba(255, 255, 255, 0.75); }
+.win-handle:focus-visible { outline: none; }
+.win-handle:focus-visible .win-flag { box-shadow: 0 0 0 3px rgba(108, 76, 241, 0.35); }
+
+/* --- Window overlay over the lanes: purely visual, never intercepts the
+   pointer — lane cells keep their hover tooltips. --- */
+.win { position: absolute; top: 0; bottom: 0; z-index: 2; pointer-events: none; }
+.festend { position: absolute; top: 0; bottom: 0; background: rgba(234, 236, 240, 0.35); border-left: 1px dashed #d5d9e2; pointer-events: none; z-index: 1; }
+.win-dim { position: absolute; top: 0; bottom: 0; background: rgba(247, 248, 250, 0.72); }
+.win-band {
+  position: absolute; top: 0; bottom: 0;
+  background: rgba(108, 76, 241, 0.05);
+  border-left: 2px solid var(--violet); border-right: 2px solid var(--violet);
+}
+
+/* Performance-time tooltip (follows the cursor over day cells). */
+.cal-tip {
+  position: fixed; z-index: 60; pointer-events: none;
+  background: var(--ink); color: #fff;
+  font-size: 0.74rem; line-height: 1.4; font-variant-numeric: tabular-nums;
+  padding: 6px 10px; border-radius: 8px; white-space: pre-line;
+  box-shadow: 0 6px 18px rgba(16, 24, 40, 0.25);
+  max-width: 280px;
+}
+
+.cal-foot {
+  display: flex; justify-content: space-between; gap: 20px;
+  margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line);
+  font-size: 0.78rem; color: var(--muted); flex-wrap: wrap;
+}
+
+/* ============ Footer ============ */
+.site-footer { background: var(--ink); color: #d9d9d9; padding: 28px 0; margin-top: 56px; }
+.footer-inner { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
+.footer-copy { color: #8c8c8c; font-size: 0.85rem; }
+
+@media (prefers-reduced-motion: reduce) {
+  .hc-num.bump { animation: none; }
+  html { scroll-behavior: auto; }
+}

content.content:
1	// Main API the UI calls: matching favourites against the show catalogue,
2	// summarizing availability within a date/time window, and (for later use) the
3	// scheduling primitives ported from edfringe/scheduling.py.
4	//
5	// Pure — no DOM, no fetch. The UI is responsible for loading data/normalized/
6	// shows.json and the favourites file text and passing them in.
7	
8	import { urlFromSlug } from "./favourites.js";
9	import {
10	  isAvailable,
11	  isNonTicketed,
12	  dateTimeToMinutes,
13	  timeToMinutesOfDay,
14	} from "./availability.js";
15	
16	// --- indexing / matching --------------------------------------------------
17	
18	/**
19	 * Index shows by slug for O(1) favourite lookup.
20	 * @param {object[]} shows shows.json array
21	 * @returns {Map<string, object>}
22	 */
23	export function buildIndex(shows) {
24	  const index = new Map();
25	  for (const show of shows || []) {
26	    if (show && show.slug) index.set(show.slug, show);
27	  }
28	  return index;
29	}
30	
31	/**
32	 * Resolve favourite slugs against the show index.
33	 * @param {string[]} slugs de-duplicated slugs from parseFavourites
34	 * @param {Map<string, object>} index from buildIndex
35	 * @returns {{matched: object[], missingSlugs: string[]}}
36	 */
37	export function matchFavourites(slugs, index) {
