+  for (const p of performances) {
+    if (!p.date.startsWith(`${YEAR}-${MONTH}-`)) continue; // outside the Aug axis — see TODO above
+    const day = Number(p.date.slice(8, 10));
+    if (day < 1 || day > DAYS_IN_MONTH) continue;
