// Smoke test for the reworked planner page: single state switch, draggable
// flag tabs, sticky rail, rail-band window drag, cell tooltip, optimizer.
import { chromium } from "playwright";

const BASE = "http://localhost:8123/plan/";
const browser = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium" });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const fails = [];
const check = (name, cond) => {
  console.log(`${cond ? "PASS" : "FAIL"}: ${name}`);
  if (!cond) fails.push(name);
};

page.on("console", (m) => { if (m.type() === "error") console.log("console.error:", m.text()); });
page.on("pageerror", (e) => { console.log("pageerror:", e.message); fails.push("pageerror: " + e.message); });

await page.goto(BASE);
check("intake visible on load", await page.locator("#screen1").isVisible());
check("calendar hidden on load", !(await page.locator("#screen2").isVisible()));
check("more-settings grid visible without clicking", await page.locator(".more-grid").isVisible());

// Load the sample favourites → state switch to the calendar.
await page.click("#sampleLink");
await page.waitForSelector("#screen2:not([hidden])", { timeout: 10000 });
check("intake hidden after favourites in", !(await page.locator("#screen1").isVisible()));
check("fav line rendered", (await page.locator("#favSummary").innerText()).includes("favourite"));
check("replace action present", await page.locator("#replaceFavBtn").isVisible());

// Flags: drag the start flag tab itself (not the line).
const flagStartText0 = await page.locator("#flagStart").innerText();
const flag = page.locator("#hStart .win-flag");
const fb = await flag.boundingBox();
await page.mouse.move(fb.x + fb.width / 2, fb.y + fb.height / 2);
await page.mouse.down();
await page.mouse.move(fb.x + fb.width / 2 + 120, fb.y + fb.height / 2, { steps: 5 });
await page.mouse.up();
const flagStartText1 = await page.locator("#flagStart").innerText();
check(`start flag drag changes date (${flagStartText0} -> ${flagStartText1})`, flagStartText0 !== flagStartText1);

// Rail band: dragging the between-space slides the whole window.
const d0 = await page.evaluate(() => document.getElementById("flagStart").textContent);
const d1a = await page.evaluate(() => document.getElementById("flagEnd").textContent);
const rb = await page.locator("#railBand").boundingBox();
await page.mouse.move(rb.x + rb.width / 2, rb.y + rb.height / 2);
await page.mouse.down();
await page.mouse.move(rb.x + rb.width / 2 - 80, rb.y + rb.height / 2, { steps: 5 });
await page.mouse.up();
const d0b = await page.evaluate(() => document.getElementById("flagStart").textContent);
const d1b = await page.evaluate(() => document.getElementById("flagEnd").textContent);
check(`rail-band drag slides window (${d0}-${d1a} -> ${d0b}-${d1b})`, d0 !== d0b && d1a !== d1b);

// Optimizer: weekend option lands on a Sat–Sun pair.
await page.selectOption("#stayLen", "wknd");
await page.click("#optimizeBtn");
const wknd = await page.evaluate(() => {
  const s = Number(document.getElementById("flagStart").textContent.split(" ")[0]);
  const e = Number(document.getElementById("flagEnd").textContent.split(" ")[0]);
  return { s, e, sd: new Date(Date.UTC(2026, 7, s)).getUTCDay(), ed: new Date(Date.UTC(2026, 7, e)).getUTCDay() };
});
check(`weekend pick is Sat-Sun (${wknd.s}-${wknd.e})`, wknd.sd === 6 && wknd.ed === 0 && wknd.e === wknd.s + 1);

// Optimizer: 4-day option gives a 4-day window.
await page.selectOption("#stayLen", "4");
await page.click("#optimizeBtn");
const four = await page.evaluate(() => {
  const s = Number(document.getElementById("flagStart").textContent.split(" ")[0]);
  const e = Number(document.getElementById("flagEnd").textContent.split(" ")[0]);
  return e - s + 1;
});
check(`4-day pick spans 4 days (got ${four})`, four === 4);

// Cell tooltip: hover a performance cell → calTip shows the time.
const cell = page.locator("#lanes .cell").filter({ has: page.locator(".seg") }).first();
await cell.hover();
const tipVisible = await page.locator("#calTip").isVisible();
const tipText = tipVisible ? await page.locator("#calTip").innerText() : "";
check(`cell hover shows time tooltip ("${tipText.split("\n")[0]}")`, tipVisible && /\d\d:\d\d/.test(tipText));

// The lanes area must not capture the pointer for window-dragging any more:
// the element under a lane cell should be the cell itself, not the overlay.
const under = await page.evaluate(() => {
  const cell = document.querySelector("#lanes .cell[data-tip]");
  const r = cell.getBoundingClientRect();
  const el = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
  return el ? el.className : "(none)";
});
check(`element under cursor over a lane mark is the cell/seg (got "${under}")`, /cell|seg/.test(under));

// Sticky rail: scroll the lane list; handles must stay visible near the top
// of the scroll container. (Sample set is small — force scrollability check
// only if it overflows; still assert sticky geometry via scrollTop.)
const sticky = await page.evaluate(() => {
  const wrap = document.getElementById("calWrap");
  wrap.scrollTop = 300;
  const st = wrap.scrollTop; // 0 if nothing to scroll
  const wrapTop = wrap.getBoundingClientRect().top;
  const railTop = document.getElementById("winRail").getBoundingClientRect().top;
  return { st, delta: railTop - wrapTop };
});
check(`rail pinned to scroll-container top (scrollTop=${sticky.st}, delta=${sticky.delta})`, sticky.delta >= -1 && sticky.delta < 40);

await page.screenshot({ path: "/tmp/claude-0/-home-user/a4cefb6d-17b2-5bc5-ada1-e6386d89091f/scratchpad/planner.png", fullPage: true });

// Replace flow: the hidden file input must still be reachable via the quiet action.
const chooserPromise = page.waitForEvent("filechooser", { timeout: 5000 }).catch(() => null);
await page.click("#replaceFavBtn");
check("replace opens a file chooser", (await chooserPromise) !== null);

// Clear returns to intake.
await page.click("#clearFavBtn");
check("clear returns to intake", await page.locator("#screen1").isVisible() && !(await page.locator("#screen2").isVisible()));

await browser.close();
if (fails.length) { console.log("\nFAILURES:", fails.length); process.exit(1); }
console.log("\nAll smoke checks passed");

