// Sticky-rail + tooltip-while-scrolled check with a 40-show favourites list.
import { chromium } from "playwright";

const browser = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium" });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const fails = [];
const check = (name, cond) => {
  console.log(`${cond ? "PASS" : "FAIL"}: ${name}`);
  if (!cond) fails.push(name);
};
page.on("pageerror", (e) => { console.log("pageerror:", e.message); fails.push("pageerror"); });

await page.goto("http://localhost:8123/plan/");
await page.setInputFiles("#csvInput", "/tmp/claude-0/-home-user/a4cefb6d-17b2-5bc5-ada1-e6386d89091f/scratchpad/many-favs.csv");
await page.waitForSelector("#screen2:not([hidden])", { timeout: 10000 });
check("calendar shown for 40-show list", true);

const sticky = await page.evaluate(() => {
  const wrap = document.getElementById("calWrap");
  wrap.scrollTop = 400;
  const st = wrap.scrollTop;
  const wrapTop = wrap.getBoundingClientRect().top;
  const railTop = document.getElementById("winRail").getBoundingClientRect().top;
  const headBottom = document.querySelector(".cal-head").getBoundingClientRect().bottom;
  return { st, railDelta: railTop - wrapTop, headDelta: headBottom - wrapTop };
});
check(`lane list scrolls (scrollTop=${sticky.st})`, sticky.st > 0);
check(`rail stays pinned while scrolled (delta=${sticky.railDelta.toFixed(1)})`, Math.abs(sticky.railDelta) < 2);
check(`day header pinned under rail (bottom=${sticky.headDelta.toFixed(1)})`, sticky.headDelta > 30 && sticky.headDelta < 110);

// Flags draggable while scrolled.
const t0 = await page.locator("#flagStart").innerText();
const fb = await page.locator("#hStart .win-flag").boundingBox();
await page.mouse.move(fb.x + fb.width / 2, fb.y + fb.height / 2);
await page.mouse.down();
await page.mouse.move(fb.x + fb.width / 2 + 100, fb.y + fb.height / 2, { steps: 4 });
await page.mouse.up();
const t1 = await page.locator("#flagStart").innerText();
check(`flag drag works while scrolled (${t0} -> ${t1})`, t0 !== t1);

// Tooltip still works on a visible cell mid-scroll.
const cell = page.locator("#lanes .cell[data-tip]").nth(200);
await cell.scrollIntoViewIfNeeded();
await cell.hover();
const tipOk = await page.locator("#calTip").isVisible();
check("tooltip works on scrolled lane", tipOk);

// Optimizer with a real list: window should land where most shows are catchable.
await page.selectOption("#stayLen", "3");
await page.click("#optimizeBtn");
await page.waitForTimeout(100);
const hero = await page.evaluate(() => ({
  in: Number(document.getElementById("hcIn").textContent),
  all: Number(document.getElementById("hcAll").textContent),
  win: document.getElementById("hcDetail").textContent,
}));
check(`optimizer picks a 3-day window with catchable shows (${hero.in}/${hero.all} in ${hero.win})`, hero.in > 0);

await page.evaluate(() => { document.getElementById("calWrap").scrollTop = 250; });
await page.screenshot({ path: "/tmp/claude-0/-home-user/a4cefb6d-17b2-5bc5-ada1-e6386d89091f/scratchpad/planner-scrolled.png" });

await browser.close();
if (fails.length) { console.log("FAILURES:", fails.length); process.exit(1); }
console.log("All scrolled-state checks passed");

